import { useState } from "react";
import type { HeadersFunction, LoaderFunctionArgs } from "react-router";
import { useLoaderData } from "react-router";
import {
  Page,
  Layout,
  Card,
  Select,
  Text,
  BlockStack,
  InlineStack,
  DataTable,
  Badge,
  ProgressBar,
  Divider,
  Icon,
  InlineGrid,
  Box,
} from "@shopify/polaris";
