import { useState, useCallback } from "react";
import type { HeadersFunction, LoaderFunctionArgs } from "react-router";
import { useNavigate, useParams } from "react-router";
import {
  Page,
  Layout,
  Card,
  Tabs,
  TextField,
  Select,
  Button,
  Badge,
  Text,
  BlockStack,
  InlineStack,
  Box,
  Divider,
  ButtonGroup,
  Tag,
  Checkbox,
  Banner,
  Icon,
} from "@shopify/polaris";
import {
  DeleteIcon,
  PlusIcon,
  DragHandleIcon,
  ImageIcon,
} from "@shopify/polaris-icons";
import { useAppBridge } from "@shopify/app-bridge-react";
import { authenticate } from "../shopify.server";
import { boundary } from "@shopify/shopify-app-react-router/server";

export const loader = async ({ request }: LoaderFunctionArgs) => {
  await authenticate.admin(request);
  return null;
};

export const headers: HeadersFunction = (headersArgs) => {
  return boundary.headers(headersArgs);
};

// --- Types ---

interface AnswerOption {
  id: string;
  label: string;
  imageUrl: string;
  mappedProducts: { id: string; title: string }[];
}

interface Question {
  id: string;
  title: string;
  type: string;
  required: boolean;
  answers: AnswerOption[];
  sliderMin?: number;
  sliderMax?: number;
  sliderStep?: number;
  sliderUnit?: string;
}

// --- Mock Data ---

const INITIAL_QUESTIONS: Question[] = [
  {
    id: "q1",
    title: "What's your skin type?",
    type: "single_choice",
    required: true,
    answers: [
      {
        id: "a1",
        label: "Oily",
        imageUrl: "",
        mappedProducts: [
          { id: "p1", title: "Oil-Free Cleanser" },
          { id: "p2", title: "Matte Moisturizer" },
        ],
      },
      {
        id: "a2",
        label: "Dry",
        imageUrl: "",
        mappedProducts: [
          { id: "p3", title: "Hydrating Serum" },
          { id: "p4", title: "Rich Cream" },
        ],
      },
      {
        id: "a3",
        label: "Combination",
        imageUrl: "",
        mappedProducts: [{ id: "p5", title: "Balance Toner" }],
      },
      {
        id: "a4",
        label: "Normal",
        imageUrl: "",
        mappedProducts: [{ id: "p6", title: "Daily Moisturizer" }],
      },
    ],
  },
  {
    id: "q2",
    title: "What's your main concern?",
    type: "multiple_choice",
    required: true,
    answers: [
      {
        id: "a5",
        label: "Acne",
        imageUrl: "",
        mappedProducts: [{ id: "p7", title: "Acne Treatment Kit" }],
      },
      {
        id: "a6",
        label: "Aging",
        imageUrl: "",
        mappedProducts: [{ id: "p8", title: "Anti-Aging Serum" }],
      },
      {
        id: "a7",
        label: "Hydration",
        imageUrl: "",
        mappedProducts: [{ id: "p9", title: "Hyaluronic Acid" }],
      },
      {
        id: "a8",
        label: "Sensitivity",
        imageUrl: "",
        mappedProducts: [{ id: "p10", title: "Gentle Care Set" }],
      },
    ],
  },
  {
    id: "q3",
    title: "What's your age range?",
    type: "dropdown",
    required: true,
    answers: [
      { id: "a9", label: "18-24", imageUrl: "", mappedProducts: [] },
      { id: "a10", label: "25-34", imageUrl: "", mappedProducts: [] },
      { id: "a11", label: "35-44", imageUrl: "", mappedProducts: [] },
      { id: "a12", label: "45+", imageUrl: "", mappedProducts: [] },
    ],
  },
];

const QUESTION_TYPES = [
  { label: "Single choice", value: "single_choice" },
  { label: "Multiple choice", value: "multiple_choice" },
  { label: "Image choice", value: "image_choice" },
  { label: "Dropdown", value: "dropdown" },
  { label: "Slider", value: "slider" },
  { label: "Yes / No", value: "yes_no" },
  { label: "Email capture", value: "email_capture" },
];

export default function QuizBuilder() {
  const navigate = useNavigate();
  const { id } = useParams();
  const shopify = useAppBridge();

  const [selectedTab, setSelectedTab] = useState(0);
  const [quizTitle, setQuizTitle] = useState("Skincare Routine Finder");
  const [quizStatus] = useState<"draft" | "live">("draft");

  // Questions Tab State
  const [questions, setQuestions] = useState<Question[]>(INITIAL_QUESTIONS);
  const [selectedQuestionIndex, setSelectedQuestionIndex] = useState(0);

  // Design Tab State
  const [quizDescription, setQuizDescription] = useState(
    "Find the perfect skincare routine for your unique skin"
  );
  const [buttonColor, setButtonColor] = useState("#008060");
  const [buttonText, setButtonText] = useState("Next");
  const [resultsHeading, setResultsHeading] = useState(
    "Here are your personalized recommendations!"
  );
  const [showProgressBar, setShowProgressBar] = useState(true);

  const selectedQuestion = questions[selectedQuestionIndex];

  const tabs = [
    { id: "questions", content: "Questions", panelID: "questions-panel" },
    { id: "mapping", content: "Product Mapping", panelID: "mapping-panel" },
    { id: "design", content: "Design", panelID: "design-panel" },
  ];

  const handleTabChange = useCallback(
    (index: number) => setSelectedTab(index),
    []
  );

  const handleSave = useCallback(() => {
    shopify.toast.show("Quiz saved successfully!");
  }, [shopify]);

  const handlePreview = useCallback(() => {
    shopify.toast.show("Opening preview...");
  }, [shopify]);

  // Question management
  const updateQuestion = useCallback(
    (field: keyof Question, value: unknown) => {
      setQuestions((prev) =>
        prev.map((q, i) =>
          i === selectedQuestionIndex ? { ...q, [field]: value } : q
        )
      );
    },
    [selectedQuestionIndex]
  );

  const addQuestion = useCallback(() => {
    const newQ: Question = {
      id: `q${Date.now()}`,
      title: "New question",
      type: "single_choice",
      required: true,
      answers: [
        {
          id: `a${Date.now()}_1`,
          label: "Option A",
          imageUrl: "",
          mappedProducts: [],
        },
        {
          id: `a${Date.now()}_2`,
          label: "Option B",
          imageUrl: "",
          mappedProducts: [],
        },
      ],
    };
    setQuestions((prev) => [...prev, newQ]);
    setSelectedQuestionIndex(questions.length);
  }, [questions.length]);

  const deleteQuestion = useCallback(
    (index: number) => {
      if (questions.length <= 1) return;
      setQuestions((prev) => prev.filter((_, i) => i !== index));
      setSelectedQuestionIndex((prev) => Math.max(0, prev - 1));
    },
    [questions.length]
  );

  const updateAnswer = useCallback(
    (answerIndex: number, field: keyof AnswerOption, value: unknown) => {
      setQuestions((prev) =>
        prev.map((q, qi) =>
          qi === selectedQuestionIndex
            ? {
                ...q,
                answers: q.answers.map((a, ai) =>
                  ai === answerIndex ? { ...a, [field]: value } : a
                ),
              }
            : q
        )
      );
    },
    [selectedQuestionIndex]
  );

  const addAnswer = useCallback(() => {
    setQuestions((prev) =>
      prev.map((q, i) =>
        i === selectedQuestionIndex
          ? {
              ...q,
              answers: [
                ...q.answers,
                {
                  id: `a${Date.now()}`,
                  label: `Option ${String.fromCharCode(65 + q.answers.length)}`,
                  imageUrl: "",
                  mappedProducts: [],
                },
              ],
            }
          : q
      )
    );
  }, [selectedQuestionIndex]);

  const deleteAnswer = useCallback(
    (answerIndex: number) => {
      setQuestions((prev) =>
        prev.map((q, i) =>
          i === selectedQuestionIndex
            ? {
                ...q,
                answers: q.answers.filter((_, ai) => ai !== answerIndex),
              }
            : q
        )
      );
    },
    [selectedQuestionIndex]
  );

  const removeProductMapping = useCallback(
    (questionIndex: number, answerIndex: number, productId: string) => {
      setQuestions((prev) =>
        prev.map((q, qi) =>
          qi === questionIndex
            ? {
                ...q,
                answers: q.answers.map((a, ai) =>
                  ai === answerIndex
                    ? {
                        ...a,
                        mappedProducts: a.mappedProducts.filter(
                          (p) => p.id !== productId
                        ),
                      }
                    : a
                ),
              }
            : q
        )
      );
    },
    []
  );

  const addMockProduct = useCallback(
    (questionIndex: number, answerIndex: number) => {
      const mockProducts = [
        "Vitamin C Serum",
        "SPF 50 Sunscreen",
        "Night Repair Cream",
        "Gentle Cleanser",
        "Eye Cream",
        "Retinol Treatment",
      ];
      const randomProduct =
        mockProducts[Math.floor(Math.random() * mockProducts.length)];
      setQuestions((prev) =>
        prev.map((q, qi) =>
          qi === questionIndex
            ? {
                ...q,
                answers: q.answers.map((a, ai) =>
                  ai === answerIndex
                    ? {
                        ...a,
                        mappedProducts: [
                          ...a.mappedProducts,
                          {
                            id: `p${Date.now()}`,
                            title: randomProduct!,
                          },
                        ],
                      }
                    : a
                ),
              }
            : q
        )
      );
      shopify.toast.show(`Product "${randomProduct}" mapped`);
    },
    [shopify]
  );

  // --- Render Questions Tab ---
  const renderQuestionsTab = () => (
    <Layout>
      <Layout.Section variant="oneThird">
        <Card>
          <BlockStack gap="300">
            <Text as="h2" variant="headingMd">
              Questions ({questions.length})
            </Text>
            <Divider />
            {questions.map((q, index) => (
              <div
                key={q.id}
                onClick={() => setSelectedQuestionIndex(index)}
                style={{
                  padding: "12px",
                  borderRadius: "8px",
                  cursor: "pointer",
                  backgroundColor:
                    index === selectedQuestionIndex
                      ? "var(--p-color-bg-surface-selected)"
                      : "transparent",
                  border:
                    index === selectedQuestionIndex
                      ? "1px solid var(--p-color-border-focus)"
                      : "1px solid transparent",
                }}
              >
                <InlineStack align="space-between" blockAlign="center">
                  <BlockStack gap="100">
                    <Text as="span" variant="bodyMd" fontWeight="semibold">
                      {index + 1}. {q.title}
                    </Text>
                    <Text as="span" variant="bodySm" tone="subdued">
                      {
                        QUESTION_TYPES.find((t) => t.value === q.type)?.label
                      }{" "}
                      · {q.answers.length} options
                    </Text>
                  </BlockStack>
                  {questions.length > 1 && (
                    <Button
                      icon={DeleteIcon}
                      variant="plain"
                      tone="critical"
                      onClick={(e) => {
                        e.stopPropagation();
                        deleteQuestion(index);
                      }}
                      accessibilityLabel="Delete question"
                    />
                  )}
                </InlineStack>
              </div>
            ))}
            <Button icon={PlusIcon} onClick={addQuestion} fullWidth>
              Add question
            </Button>
          </BlockStack>
        </Card>
      </Layout.Section>

      <Layout.Section>
        {selectedQuestion && (
          <Card>
            <BlockStack gap="400">
              <Text as="h2" variant="headingMd">
                Edit Question {selectedQuestionIndex + 1}
              </Text>
              <Divider />

              <TextField
                label="Question title"
                value={selectedQuestion.title}
                onChange={(val) => updateQuestion("title", val)}
                autoComplete="off"
              />

              <Select
                label="Question type"
                options={QUESTION_TYPES}
                value={selectedQuestion.type}
                onChange={(val) => updateQuestion("type", val)}
              />

              <Checkbox
                label="Required"
                checked={selectedQuestion.required}
                onChange={(val) => updateQuestion("required", val)}
              />

              {selectedQuestion.type === "slider" ? (
                <BlockStack gap="300">
                  <Text as="h3" variant="headingSm">
                    Slider Settings
                  </Text>
                  <InlineStack gap="300">
                    <div style={{ flex: 1 }}>
                      <TextField
                        label="Min"
                        type="number"
                        value={String(selectedQuestion.sliderMin || 0)}
                        onChange={(val) =>
                          updateQuestion("sliderMin", parseInt(val))
                        }
                        autoComplete="off"
                      />
                    </div>
                    <div style={{ flex: 1 }}>
                      <TextField
                        label="Max"
                        type="number"
                        value={String(selectedQuestion.sliderMax || 100)}
                        onChange={(val) =>
                          updateQuestion("sliderMax", parseInt(val))
                        }
                        autoComplete="off"
                      />
                    </div>
                    <div style={{ flex: 1 }}>
                      <TextField
                        label="Step"
                        type="number"
                        value={String(selectedQuestion.sliderStep || 1)}
                        onChange={(val) =>
                          updateQuestion("sliderStep", parseInt(val))
                        }
                        autoComplete="off"
                      />
                    </div>
                  </InlineStack>
                  <TextField
                    label="Unit label"
                    value={selectedQuestion.sliderUnit || ""}
                    onChange={(val) => updateQuestion("sliderUnit", val)}
                    placeholder="e.g., years, ml, %"
                    autoComplete="off"
                  />
                </BlockStack>
              ) : selectedQuestion.type === "email_capture" ? (
                <Banner tone="info">
                  <p>
                    Email capture questions collect the shopper's email address.
                    Configure default text in Settings → Email Capture.
                  </p>
                </Banner>
              ) : (
                <BlockStack gap="300">
                  <Text as="h3" variant="headingSm">
                    Answer Options
                  </Text>
                  {selectedQuestion.answers.map((answer, ai) => (
                    <InlineStack key={answer.id} gap="200" blockAlign="end">
                      <div style={{ flex: 1 }}>
                        <TextField
                          label={`Option ${ai + 1}`}
                          labelHidden
                          value={answer.label}
                          onChange={(val) => updateAnswer(ai, "label", val)}
                          autoComplete="off"
                          prefix={`${ai + 1}.`}
                        />
                      </div>
                      {selectedQuestion.type === "image_choice" && (
                        <Button icon={ImageIcon} accessibilityLabel="Add image">
                          Image
                        </Button>
                      )}
                      {selectedQuestion.answers.length > 2 && (
                        <Button
                          icon={DeleteIcon}
                          variant="plain"
                          tone="critical"
                          onClick={() => deleteAnswer(ai)}
                          accessibilityLabel="Delete option"
                        />
                      )}
                    </InlineStack>
                  ))}
                  <Button icon={PlusIcon} onClick={addAnswer}>
                    Add option
                  </Button>
                </BlockStack>
              )}
            </BlockStack>
          </Card>
        )}
      </Layout.Section>
    </Layout>
  );

  // --- Render Product Mapping Tab ---
  const renderMappingTab = () => (
    <Layout>
      <Layout.Section>
        <BlockStack gap="500">
          <Banner tone="info">
            <p>
              Map Shopify products to each answer option. When a shopper selects
              an answer, the mapped products will be recommended.
            </p>
          </Banner>

          {questions
            .filter(
              (q) =>
                q.type !== "email_capture" &&
                q.type !== "slider"
            )
            .map((question, qi) => (
              <Card key={question.id}>
                <BlockStack gap="400">
                  <InlineStack align="space-between">
                    <Text as="h2" variant="headingMd">
                      {qi + 1}. {question.title}
                    </Text>
                    <Badge>
                      {
                        QUESTION_TYPES.find((t) => t.value === question.type)
                          ?.label
                      }
                    </Badge>
                  </InlineStack>
                  <Divider />

                  {question.answers.map((answer, ai) => {
                    const actualQi = questions.findIndex(
                      (q) => q.id === question.id
                    );
                    return (
                      <Box
                        key={answer.id}
                        padding="300"
                        borderWidth="025"
                        borderRadius="200"
                        borderColor="border"
                      >
                        <BlockStack gap="300">
                          <InlineStack
                            align="space-between"
                            blockAlign="center"
                          >
                            <Text as="span" variant="bodyMd" fontWeight="bold">
                              {answer.label}
                            </Text>
                            <Button
                              size="slim"
                              onClick={() => addMockProduct(actualQi, ai)}
                            >
                              + Browse products
                            </Button>
                          </InlineStack>

                          {answer.mappedProducts.length > 0 ? (
                            <InlineStack gap="200" wrap>
                              {answer.mappedProducts.map((product) => (
                                <Tag
                                  key={product.id}
                                  onRemove={() =>
                                    removeProductMapping(
                                      actualQi,
                                      ai,
                                      product.id
                                    )
                                  }
                                >
                                  {product.title}
                                </Tag>
                              ))}
                            </InlineStack>
                          ) : (
                            <Text as="span" variant="bodySm" tone="subdued">
                              No products mapped yet
                            </Text>
                          )}
                        </BlockStack>
                      </Box>
                    );
                  })}
                </BlockStack>
              </Card>
            ))}
        </BlockStack>
      </Layout.Section>
    </Layout>
  );

  // --- Render Design Tab ---
  const renderDesignTab = () => (
    <Layout>
      <Layout.Section>
        <Card>
          <BlockStack gap="400">
            <Text as="h2" variant="headingMd">
              Quiz Appearance
            </Text>
            <Divider />

            <TextField
              label="Quiz title"
              value={quizTitle}
              onChange={setQuizTitle}
              autoComplete="off"
            />

            <TextField
              label="Quiz description"
              value={quizDescription}
              onChange={setQuizDescription}
              multiline={3}
              autoComplete="off"
            />

            <TextField
              label="Primary button color"
              value={buttonColor}
              onChange={setButtonColor}
              autoComplete="off"
              prefix="#"
              helpText="Enter a hex color code (e.g., 008060)"
              connectedRight={
                <div
                  style={{
                    width: "36px",
                    height: "36px",
                    borderRadius: "4px",
                    backgroundColor: buttonColor.startsWith("#")
                      ? buttonColor
                      : `#${buttonColor}`,
                    border: "1px solid var(--p-color-border)",
                  }}
                />
              }
            />

            <TextField
              label="Button text"
              value={buttonText}
              onChange={setButtonText}
              autoComplete="off"
              helpText="Text shown on the next/submit button"
            />

            <TextField
              label="Results page heading"
              value={resultsHeading}
              onChange={setResultsHeading}
              autoComplete="off"
              helpText="Heading shown on the results/recommendations page"
            />

            <Checkbox
              label="Show progress bar"
              checked={showProgressBar}
              onChange={setShowProgressBar}
              helpText="Displays a progress indicator showing quiz completion percentage"
            />
          </BlockStack>
        </Card>
      </Layout.Section>

      <Layout.Section variant="oneThird">
        <Card>
          <BlockStack gap="300">
            <Text as="h2" variant="headingMd">
              Preview
            </Text>
            <Divider />
            <Box
              padding="400"
              borderRadius="200"
              background="bg-surface-secondary"
            >
              <BlockStack gap="300">
                {showProgressBar && (
                  <div
                    style={{
                      height: "4px",
                      backgroundColor: "#e0e0e0",
                      borderRadius: "2px",
                      overflow: "hidden",
                    }}
                  >
                    <div
                      style={{
                        width: "33%",
                        height: "100%",
                        backgroundColor: buttonColor.startsWith("#")
                          ? buttonColor
                          : `#${buttonColor}`,
                        borderRadius: "2px",
                      }}
                    />
                  </div>
                )}
                <Text as="h3" variant="headingLg" alignment="center">
                  {quizTitle}
                </Text>
                <Text as="p" variant="bodySm" tone="subdued" alignment="center">
                  {quizDescription}
                </Text>
                <Divider />
                <Text as="p" variant="bodyMd" fontWeight="semibold">
                  {questions[0]?.title || "Your question here"}
                </Text>
                <BlockStack gap="200">
                  {(questions[0]?.answers || []).slice(0, 3).map((a) => (
                    <Box
                      key={a.id}
                      padding="200"
                      borderWidth="025"
                      borderRadius="200"
                      borderColor="border"
                    >
                      <Text as="span" variant="bodySm">
                        {a.label}
                      </Text>
                    </Box>
                  ))}
                </BlockStack>
                <div style={{ textAlign: "center", paddingTop: "8px" }}>
                  <div
                    style={{
                      display: "inline-block",
                      padding: "8px 24px",
                      borderRadius: "6px",
                      color: "white",
                      fontWeight: 600,
                      fontSize: "14px",
                      backgroundColor: buttonColor.startsWith("#")
                        ? buttonColor
                        : `#${buttonColor}`,
                    }}
                  >
                    {buttonText}
                  </div>
                </div>
              </BlockStack>
            </Box>
          </BlockStack>
        </Card>
      </Layout.Section>
    </Layout>
  );

  return (
    <Page
      backAction={{ content: "Quizzes", onAction: () => navigate("/app/quizzes") }}
      title={quizTitle}
      titleMetadata={
        <Badge tone={quizStatus === "live" ? "success" : "attention"}>
          {quizStatus === "live" ? "Live" : "Draft"}
        </Badge>
      }
      primaryAction={{
        content: "Save quiz",
        onAction: handleSave,
      }}
      secondaryActions={[
        {
          content: "Preview",
          onAction: handlePreview,
        },
      ]}
    >
      <BlockStack gap="400">
        <Tabs tabs={tabs} selected={selectedTab} onSelect={handleTabChange}>
          <Box paddingBlockStart="400">
            {selectedTab === 0 && renderQuestionsTab()}
            {selectedTab === 1 && renderMappingTab()}
            {selectedTab === 2 && renderDesignTab()}
          </Box>
        </Tabs>
      </BlockStack>
    </Page>
  );
}

