import type React from "react";
import type { HeadersFunction, LoaderFunctionArgs } from "react-router";
import { Outlet, useLoaderData, useRouteError, isRouteErrorResponse } from "react-router";
import { boundary } from "@shopify/shopify-app-react-router/server";
import { AppProvider } from "@shopify/shopify-app-react-router/react";
import polarisStyles from "@shopify/polaris/build/esm/styles.css?url";
import { AppProvider as PolarisProvider, Page, Banner, BlockStack, Text } from "@shopify/polaris";
import enTranslations from "@shopify/polaris/locales/en.json";

import { authenticate } from "../shopify.server";

export const links = () => [{ rel: "stylesheet", href: polarisStyles }];

export const loader = async ({ request }: LoaderFunctionArgs) => {
  await authenticate.admin(request);
  return { apiKey: process.env.SHOPIFY_API_KEY || "" };
};

export default function App() {
  const { apiKey } = useLoaderData<typeof loader>();

  return (
    <PolarisProvider i18n={enTranslations}>
      <AppProvider embedded apiKey={apiKey}>
        <s-app-nav>
          <s-link href="/app">Dashboard</s-link>
          <s-link href="/app/quizzes">My Quizzes</s-link>
          <s-link href="/app/analytics">Analytics</s-link>
          <s-link href="/app/integrations">Integrations</s-link>
          <s-link href="/app/billing">Billing</s-link>
          <s-link href="/app/settings">Settings</s-link>
          <s-link href="/app/help">Help Center</s-link>
        </s-app-nav>
        <Outlet />
      </AppProvider>
    </PolarisProvider>
  );
}

export function ErrorBoundary() {
  const error = useRouteError();

  // Shopify handles auth redirect responses (302) — delegate to SDK
  if (error instanceof Response && error.status === 302) {
    return boundary.error(error) as React.ReactElement;
  }

  // Route-level 404 / 400 errors
  if (isRouteErrorResponse(error)) {
    return (
      <Page title="Error">
        <Banner tone="critical" title={`${error.status} — ${error.statusText || "Error"}`}>
          <BlockStack gap="200">
            <Text as="p">{error.data?.error ?? "Something went wrong."}</Text>
          </BlockStack>
        </Banner>
      </Page>
    );
  }

  // Unexpected errors
  return (
    <Page title="Something went wrong">
      <Banner tone="critical" title="Application error">
        <Text as="p">Please refresh the page. If the problem persists, contact support.</Text>
      </Banner>
    </Page>
  );
}

export const headers: HeadersFunction = (headersArgs) => {
  return boundary.headers(headersArgs);
};

