/**
 * Safe App Bridge toast — no-ops during SSR, works in browser via CDN App Bridge.
 */
export function showToast(message: string, options?: { isError?: boolean }) {
  if (typeof window !== "undefined") {
    const shopify = (window as Window & { shopify?: { toast?: { show: (msg: string, opts?: { isError?: boolean }) => void } } }).shopify;
    shopify?.toast?.show(message, options);
  }
}

