import { showToast } from "~/utils/toast";
import type { ActionFunctionArgs, HeadersFunction, LoaderFunctionArgs } from "react-router";
import { useLoaderData, useActionData, useNavigation, Form } from "react-router";
import {
  Page,
  Card,
  Text,
  InlineStack,
  BlockStack,
  Button,
  Badge,
  List,
  Divider,
  Banner,
  SkeletonPage,
  SkeletonBodyText,
} from "@shopify/polaris";
import { useEffect } from "react";
import { data } from "react-router";
import { authenticate } from "../shopify.server";
import { boundary } from "@shopify/shopify-app-react-router/server";
import db from "../db.server";

const PLANS = [
  {
    id: "free",
    name: "Free",
    price: "$0",
    period: "forever",
    quizLimit: 1,
    responseLimit: "100/mo",
    features: [
      "1 active quiz",
      "100 responses/month",
      "Basic analytics",
      "QuizSnap branding",
    ],
    cta: "Current plan",
    highlight: false,
  },
  {
    id: "starter",
    name: "Starter",
    price: "$9.99",
    period: "/month",
    quizLimit: 5,
    responseLimit: "1,000/mo",
    features: [
      "5 active quizzes",
      "1,000 responses/month",
      "Basic analytics",
      "1 email integration",
      "Remove branding",
    ],
    cta: "Upgrade to Starter",
    highlight: false,
  },
  {
    id: "pro",
    name: "Pro",
    price: "$29.99",
    period: "/month",
    quizLimit: -1,
    responseLimit: "10,000/mo",
    features: [
      "Unlimited quizzes",
      "10,000 responses/month",
      "Full analytics",
      "All email integrations",
      "A/B testing",
      "CSV export",
      "Custom branding",
    ],
    cta: "Upgrade to Pro",
    highlight: true,
  },
  {
    id: "enterprise",
    name: "Enterprise",
    price: "$79.99",
    period: "/month",
    quizLimit: -1,
    responseLimit: "Unlimited",
    features: [
      "Everything in Pro",
      "Unlimited responses",
      "API access",
      "Priority support",
      "Custom widget domain",
    ],
    cta: "Upgrade to Enterprise",
    highlight: false,
  },
] as const;

type PlanId = (typeof PLANS)[number]["id"];

const PLAN_LIMITS: Record<PlanId, { quizLimit: number; responseLimit: number }> = {
  free: { quizLimit: 1, responseLimit: 100 },
  starter: { quizLimit: 5, responseLimit: 1000 },
  pro: { quizLimit: 999, responseLimit: 10000 },
  enterprise: { quizLimit: 999, responseLimit: 999999 },
};

export const loader = async ({ request }: LoaderFunctionArgs) => {
  const { session } = await authenticate.admin(request);

  try {
    const startOfMonth = new Date();
    startOfMonth.setDate(1);
    startOfMonth.setHours(0, 0, 0, 0);

    const [sub, quizCount, responseCount] = await Promise.all([
      db.subscription.findUnique({ where: { shop: session.shop } }),
      db.quiz.count({
        where: { shop: session.shop, status: { not: "archived" } },
      }),
      db.quizResponse.count({
        where: {
          shop: session.shop,
          createdAt: { gte: startOfMonth },
        },
      }),
    ]);

    return {
      currentPlan: (sub?.planId ?? "free") as PlanId,
      planStatus: sub?.status ?? "active",
      quizCount,
      responseCount,
      trialEndsAt: sub?.trialEndsAt?.toISOString() ?? null,
    };
  } catch (error) {
    console.error("Billing loader error:", error);
    return {
      currentPlan: "free" as PlanId,
      planStatus: "active",
      quizCount: 0,
      responseCount: 0,
      trialEndsAt: null,
    };
  }
};

export const action = async ({ request }: ActionFunctionArgs) => {
  const { session } = await authenticate.admin(request);
  const formData = await request.formData();
  const planId = String(formData.get("planId") ?? "") as PlanId;

  const validPlans: PlanId[] = ["free", "starter", "pro", "enterprise"];
  if (!validPlans.includes(planId)) {
    return data({ error: "Invalid plan selected" }, { status: 400 });
  }

  try {
    const limits = PLAN_LIMITS[planId];
    await db.subscription.upsert({
      where: { shop: session.shop },
      create: {
        shop: session.shop,
        planId,
        status: "active",
        quizLimit: limits.quizLimit,
        responseLimit: limits.responseLimit,
      },
      update: {
        planId,
        status: "active",
        quizLimit: limits.quizLimit,
        responseLimit: limits.responseLimit,
      },
    });

    const planName = PLANS.find((p) => p.id === planId)?.name ?? planId;
    const message =
      planId === "free"
        ? "Downgraded to Free plan"
        : `Upgraded to ${planName} plan successfully!`;

    return { success: true, message };
  } catch (error) {
    console.error("Billing action error:", error);
    return data(
      { error: "Failed to update plan. Please try again." },
      { status: 500 },
    );
  }
};

export default function BillingPage() {
  const { currentPlan, planStatus, quizCount, responseCount, trialEndsAt } =
    useLoaderData<typeof loader>();
  const actionData = useActionData<typeof action>();
  const navigation = useNavigation();
  const isUpdating = navigation.state === "submitting";

  useEffect(() => {
    if (actionData && "success" in actionData && actionData.success) {
      showToast(actionData.message ?? "Plan updated!");
    }
    if (actionData && "error" in actionData && actionData.error) {
      showToast(actionData.error, { isError: true });
    }
  }, [actionData]);

  const currentPlanData = PLANS.find((p) => p.id === currentPlan) ?? PLANS[0];
  const submittingPlanId = navigation.formData?.get("planId") as string | null;

  return (
    <Page
      title="Plans & Billing"
      subtitle="Choose the right plan for your store"
    >
      <BlockStack gap="600">
        {actionData && "error" in actionData && actionData.error && (
          <Banner tone="critical" title="Update failed">
            <p>{actionData.error}</p>
          </Banner>
        )}

        {trialEndsAt && (
          <Banner tone="info" title="Trial period active">
            <p>
              Your trial ends on{" "}
              {new Date(trialEndsAt).toLocaleDateString("en-US", {
                year: "numeric",
                month: "long",
                day: "numeric",
              })}
              . Upgrade to keep your features.
            </p>
          </Banner>
        )}

        {/* Current usage summary */}
        <Card>
          <BlockStack gap="400">
            <InlineStack align="space-between" blockAlign="center">
              <Text as="h2" variant="headingMd">
                Current plan
              </Text>
              <InlineStack gap="200">
                <Badge tone={currentPlan === "free" ? undefined : "success"}>
                  {currentPlanData.name}
                </Badge>
                {planStatus === "frozen" && (
                  <Badge tone="warning">Frozen</Badge>
                )}
              </InlineStack>
            </InlineStack>
            <InlineStack gap="800" wrap={false}>
              <BlockStack gap="100">
                <Text as="p" variant="bodySm" tone="subdued">
                  Active quizzes
                </Text>
                <Text as="p" variant="headingLg" fontWeight="bold">
                  {quizCount}
                </Text>
                <Text as="p" variant="bodySm" tone="subdued">
                  of{" "}
                  {currentPlanData.quizLimit === -1
                    ? "unlimited"
                    : currentPlanData.quizLimit}
                </Text>
              </BlockStack>
              <BlockStack gap="100">
                <Text as="p" variant="bodySm" tone="subdued">
                  Responses this month
                </Text>
                <Text as="p" variant="headingLg" fontWeight="bold">
                  {responseCount.toLocaleString()}
                </Text>
                <Text as="p" variant="bodySm" tone="subdued">
                  of {currentPlanData.responseLimit}
                </Text>
              </BlockStack>
            </InlineStack>
          </BlockStack>
        </Card>

        {/* Plan comparison grid */}
        <div
          style={{
            display: "grid",
            gridTemplateColumns: "repeat(auto-fit, minmax(220px, 1fr))",
            gap: "16px",
          }}
        >
          {PLANS.map((plan) => {
            const isCurrent = plan.id === currentPlan;
            const isThisSubmitting =
              isUpdating && submittingPlanId === plan.id;

            return (
              <div
                key={plan.id}
                style={{
                  border: plan.highlight
                    ? "2px solid var(--p-color-border-emphasis)"
                    : "1px solid var(--p-color-border)",
                  borderRadius: "var(--p-border-radius-300)",
                  padding: "20px",
                  position: "relative",
                  background: isCurrent
                    ? "var(--p-color-bg-surface-secondary)"
                    : "var(--p-color-bg-surface)",
                }}
              >
                {plan.highlight && (
                  <div
                    style={{
                      position: "absolute",
                      top: -12,
                      left: "50%",
                      transform: "translateX(-50%)",
                    }}
                  >
                    <Badge tone="success">Most Popular</Badge>
                  </div>
                )}

                <BlockStack gap="400">
                  <BlockStack gap="100">
                    <Text as="h3" variant="headingMd" fontWeight="bold">
                      {plan.name}
                    </Text>
                    <InlineStack gap="100" blockAlign="end">
                      <Text
                        as="span"
                        variant="headingXl"
                        fontWeight="bold"
                      >
                        {plan.price}
                      </Text>
                      <Text as="span" variant="bodyMd" tone="subdued">
                        {plan.period}
                      </Text>
                    </InlineStack>
                  </BlockStack>

                  <Divider />

                  <List type="bullet">
                    {plan.features.map((f) => (
                      <List.Item key={f}>{f}</List.Item>
                    ))}
                  </List>

                  <Form method="post">
                    <input type="hidden" name="planId" value={plan.id} />
                    <Button
                      submit
                      variant={plan.highlight ? "primary" : "secondary"}
                      disabled={isCurrent || isUpdating}
                      loading={isThisSubmitting}
                      fullWidth
                      tone={
                        !isCurrent && plan.id === "free"
                          ? "critical"
                          : undefined
                      }
                    >
                      {isCurrent ? "Current plan" : plan.cta}
                    </Button>
                  </Form>
                </BlockStack>
              </div>
            );
          })}
        </div>

        {/* Footer note */}
        <Text as="p" variant="bodySm" tone="subdued" alignment="center">
          All plans include a 7-day free trial. Cancel anytime. Prices in USD.
        </Text>
      </BlockStack>
    </Page>
  );
}

export function HydrateFallback() {
  return (
    <SkeletonPage title="Plans & Billing">
      <SkeletonBodyText lines={10} />
    </SkeletonPage>
  );
}

export const headers: HeadersFunction = (headersArgs) => {
  return boundary.headers(headersArgs);
};

