                      top: -12,
                      left: "50%",
                      transform: "translateX(-50%)",
                      whiteSpace: "nowrap",
                    }}
                  >
                    <Badge tone="success">Current plan</Badge>
                  </div>
                )}

                <BlockStack gap="400">
                  {/* Plan name + price */}
                  <BlockStack gap="200">
                    <Text as="h3" variant="headingMd" fontWeight="bold">
