                        loading={isThisSubmitting}
                        fullWidth
                        tone={ctaTone}
                        size="large"
                      >
                        {isCurrent ? "Current plan" : ctaText}
                      </Button>
                    </Form>
                  </div>
                </BlockStack>
              </div>
            );
          })}
        </InlineGrid>

        {/* ── Feature comparison table ──────────────────────── */}
        <Card>
          <BlockStack gap="400">
