                    marginBottom: 4,
                  }}
                >
                  <Text as="span" variant="bodySm" fontWeight="bold">
                    Feature
                  </Text>
                  <Text
                    as="span"
                    variant="bodySm"
                    fontWeight="bold"
                    alignment="center"
                  >
                    Free
                  </Text>
                  <Text
                    as="span"
                    variant="bodySm"
                    fontWeight="bold"
                    alignment="center"
                  >
                    Starter
                  </Text>
                  <Text
                    as="span"
                    variant="bodySm"
                    fontWeight="bold"
                    alignment="center"
