122→
123→type FeatureValue = boolean | string;
124→
125→const FEATURE_ROWS: { label: string; free: FeatureValue; starter: FeatureValue; pro: FeatureValue; ultimate: FeatureValue }[] = [
126→  { label: "Zip codes", free: "20", starter: "500", pro: "Unlimited", ultimate: "Unlimited" },
127→  { label: "Blocked zip codes", free: false, starter: false, pro: true, ultimate: true },
