129→  { label: "Waitlist entries", free: false, starter: "25", pro: "Unlimited", ultimate: "Unlimited" },
130→  { label: "Widget customization", free: false, starter: true, pro: true, ultimate: true },
131→  { label: "Delivery ETA & COD", free: false, starter: true, pro: true, ultimate: true },
132→  { label: "Zone organization", free: false, starter: true, pro: true, ultimate: true },
133→  { label: "CSV import", free: false, starter: true, pro: true, ultimate: true },
134→  { label: "CSV export", free: false, starter: false, pro: true, ultimate: true },
