418→// ─── Page ─────────────────────────────────────────────────────────────────────
419→
420→export default function PricingPage() {
421→  const { subscription, isAdmin } = useLoaderData<typeof loader>();
422→  const fetcher = useFetcher<typeof action>();
423→  const navigate = useNavigate();
424→  const shopify = useAppBridge();
425→
426→  const [isAnnual, setIsAnnual] = useState(
427→    subscription.billingInterval === "annual",
428→  );
429→  const [loadingPlan, setLoadingPlan] = useState<string | null>(null);
430→  const [cancelModalOpen, setCancelModalOpen] = useState(false);
431→
432→  const data = fetcher.data;
433→  const isFetching = fetcher.state !== "idle";
434→
435→  useEffect(() => {
436→    if (!isFetching) setLoadingPlan(null);
437→    if (data && "message" in data && data.message) {
438→      shopify.toast.show(data.message as string);
