441→
442→  const actionError =
443→    data && "error" in data && data.error ? (data.error as string) : null;
444→
445→  const handleSubscribe = useCallback(
446→    (planName: string) => {
447→      setLoadingPlan(planName);
448→      const fd = new FormData();
449→      fd.set("intent", "subscribe");
450→      fd.set("plan", planName);
451→      fetcher.submit(fd, { method: "POST" });
452→    },
453→    [fetcher],
454→  );
455→
456→  const handleConfirmCancel = useCallback(() => {
457→    setCancelModalOpen(false);
458→    setLoadingPlan("cancel");
459→    const fd = new FormData();
460→    fd.set("intent", "cancel");
461→    fetcher.submit(fd, { method: "POST" });
462→  }, [fetcher]);
463→
464→  const currentTier = subscription.planTier;
465→  const isFreeTier = currentTier === "free";
466→
467→  return (
468→    <Page
469→      title="Pricing"
470→      subtitle="Choose the plan that's right for your store"
471→      backAction={{ onAction: () => navigate("/app") }}
472→    >
473→      <Box paddingBlockEnd="1600">
474→        <BlockStack gap="600">
475→
476→          {/* Error banner */}
477→          {actionError && (
478→            <Banner tone="critical" title="Billing error">
479→              <Text as="p" variant="bodyMd">{actionError}</Text>
480→            </Banner>
481→          )}
482→
483→          {/* Billing toggle */}
484→          <InlineStack align="center">
485→            <ButtonGroup variant="segmented">
486→              <Button
487→                pressed={!isAnnual}
488→                onClick={() => setIsAnnual(false)}
489→              >
490→                Monthly
491→              </Button>
492→              <Button
493→                pressed={isAnnual}
494→                onClick={() => setIsAnnual(true)}
495→              >
496→                Annual · Save up to 38%
497→              </Button>
498→            </ButtonGroup>
499→          </InlineStack>
500→
501→          {/* Free plan — full-width card */}
502→          <Card padding="0">
503→            <Box padding="500">
504→              <BlockStack gap="400">
505→                {/* Top row: info + price + button */}
506→                <InlineGrid columns={{ xs: 1, md: "1fr auto auto" }} gap="400" alignItems="center">
507→                  <BlockStack gap="050">
508→                    <InlineStack gap="200" blockAlign="center" wrap={false}>
509→                      <Text as="h3" variant="headingLg" fontWeight="bold">
510→                        Free
511→                      </Text>
512→                      {isFreeTier && <Badge tone="success">Active</Badge>}
513→                    </InlineStack>
514→                    <Text as="p" variant="bodyMd" tone="subdued">
515→                      {PLANS_DATA.free.description}
516→                    </Text>
517→                  </BlockStack>
518→
519→                  <InlineStack gap="100" blockAlign="baseline" wrap={false}>
520→                    <Text as="p" variant="heading2xl" fontWeight="bold">
