import { useState, useEffect, useCallback } from "react";
import type {
  ActionFunctionArgs,
  HeadersFunction,
  LoaderFunctionArgs,
} from "react-router";
import {
  useFetcher,
  useLoaderData,
  useNavigate,
  useRouteError,
} from "react-router";
import { showToast } from "../utils/toast";
import { boundary } from "@shopify/shopify-app-react-router/server";
import { authenticate } from "../shopify.server";
import db from "../db.server";
import {
  Page,
  Card,
  BlockStack,
  InlineStack,
  Text,
  Badge,
  Button,
  ButtonGroup,
  Divider,
  Box,
  Banner,
  Icon,
  Modal,
  InlineGrid,
  SkeletonPage,
  SkeletonBodyText,
  SkeletonDisplayText,
} from "@shopify/polaris";
import { CheckCircleIcon, XCircleIcon } from "@shopify/polaris-icons";

// ─── Plan data ────────────────────────────────────────────────────────────────

const PLANS_DATA = {
  free: {
    id: "free",
    name: "Free",
    monthlyPrice: 0,
    annualPrice: 0,
    annualMonthlyPrice: 0,
    description: "Get started with product quizzes — no credit card needed",
    features: [
      "1 active quiz",
      "100 responses/month",
      "All question types",
      "Basic analytics",
      "Standard email support",
    ],
    quizLimit: 1,
    responseLimit: 100,
  },
  starter: {
    id: "starter",
    name: "Starter",
    monthlyPrice: 29,
    annualPrice: 228,
    annualMonthlyPrice: 19,
    description: "Essential features for growing stores",
    features: [
      "5 active quizzes",
      "Unlimited responses",
      "Advanced analytics",
      "Remove QuizSnap branding",
      "Klaviyo integration",
      "Webhook integration",
      "Email capture",
      "CSV export",
    ],
    quizLimit: 5,
    responseLimit: 999999,
  },
  pro: {
    id: "pro",
    name: "Pro",
    monthlyPrice: 79,
    annualPrice: 588,
    annualMonthlyPrice: 49,
    description: "Full power for brands that rely on personalisation",
    features: [
      "Unlimited quizzes",
      "Unlimited responses",
      "Full analytics suite",
      "All email integrations",
      "AI auto-mapping",
      "A/B testing",
      "Shopify Flow trigger",
      "Priority support",
    ],
    quizLimit: 999,
    responseLimit: 999999,
    bestValue: true as const,
  },
};

// ─── Feature comparison rows ─────────────────────────────────────────────────

type FeatureValue = boolean | string;

const FEATURE_ROWS: {
  label: string;
  free: FeatureValue;
  starter: FeatureValue;
  pro: FeatureValue;
}[] = [
  { label: "Active quizzes", free: "1", starter: "5", pro: "Unlimited" },
  {
    label: "Monthly responses",
    free: "100",
    starter: "Unlimited",
    pro: "Unlimited",
  },
  { label: "Question types", free: "All", starter: "All", pro: "All" },
  {
    label: "Analytics",
    free: "Basic",
    starter: "Advanced",
    pro: "Full suite",
  },
  {
    label: "QuizSnap branding",
    free: "Shown",
    starter: "Hidden",
    pro: "Hidden",
  },
  { label: "Email capture", free: false, starter: true, pro: true },
  { label: "Klaviyo integration", free: false, starter: true, pro: true },
  { label: "Webhook integration", free: false, starter: true, pro: true },
  { label: "Omnisend integration", free: false, starter: false, pro: true },
  { label: "Shopify Flow trigger", free: false, starter: false, pro: true },
  { label: "A/B testing", free: false, starter: false, pro: true },
  { label: "AI auto-mapping", free: false, starter: false, pro: true },
  { label: "CSV export", free: false, starter: true, pro: true },
  { label: "Custom branding", free: false, starter: false, pro: true },
  {
    label: "Priority support",
    free: false,
    starter: false,
    pro: true,
  },
];

const PLAN_ORDER = ["free", "starter", "pro"] as const;

const TIER_ORDER: Record<string, number> = {
  free: 0,
  starter: 1,
  pro: 2,
};

// ─── Loader ───────────────────────────────────────────────────────────────────

export const loader = async ({ request }: LoaderFunctionArgs) => {
  const { session } = await authenticate.admin(request);
  const shop = session.shop;

  try {
    const sub = await db.subscription.findUnique({ where: { shop } });
    return {
      currentTier: (sub?.planId ?? "free") as keyof typeof PLANS_DATA,
      billingInterval: sub?.billingInterval ?? "monthly",
      planStatus: sub?.status ?? "active",
    };
  } catch {
    return {
      currentTier: "free" as keyof typeof PLANS_DATA,
      billingInterval: "monthly",
      planStatus: "active",
    };
  }
};

// ─── Action ───────────────────────────────────────────────────────────────────

export const action = async ({
  request,
}: ActionFunctionArgs): Promise<
  { error: string } | { success: boolean; message: string } | null
> => {
  const { session } = await authenticate.admin(request);
  const shop = session.shop;
  const formData = await request.formData();
  const intent = String(formData.get("intent"));

  if (intent === "subscribe") {
    const planId = String(formData.get("planId")) as keyof typeof PLANS_DATA;
    const interval = String(formData.get("interval")) as
      | "monthly"
      | "annual";

    const plan = PLANS_DATA[planId];
    if (!plan || planId === "free") {
      return { error: "Invalid plan selected" };
    }

    try {
      await db.subscription.upsert({
        where: { shop },
        create: {
          shop,
          planId,
          billingInterval: interval,
          status: "active",
          quizLimit: plan.quizLimit,
          responseLimit: plan.responseLimit,
          trialEndsAt: new Date(Date.now() + 7 * 24 * 60 * 60 * 1000),
        },
        update: {
          planId,
          billingInterval: interval,
          status: "active",
          quizLimit: plan.quizLimit,
          responseLimit: plan.responseLimit,
        },
      });

      return {
        success: true,
        message: `Upgraded to ${plan.name} — 7-day free trial started!`,
      };
    } catch {
      return { error: "Failed to initiate subscription. Please try again." };
    }
  }

  if (intent === "cancel") {
    try {
      await db.subscription.upsert({
        where: { shop },
        create: {
          shop,
          planId: "free",
          status: "active",
          quizLimit: 1,
          responseLimit: 100,
        },
        update: {
          planId: "free",
          status: "active",
          quizLimit: 1,
          responseLimit: 100,
          shopifySubscriptionId: null,
        },
      });
      return {
        success: true,
        message: "Subscription cancelled. You are now on the Free plan.",
      };
    } catch {
      return { error: "Failed to cancel subscription. Please try again." };
    }
  }

  return null;
};

// ─── Sub-components ──────────────────────────────────────────────────────────

function PlanFeature({ feature }: { feature: string }) {
  return (
    <InlineStack gap="200" blockAlign="start" wrap={false}>
      <Box>
        <Icon source={CheckCircleIcon} tone="success" />
      </Box>
      <Text as="span" variant="bodyLg">
        {feature}
      </Text>
    </InlineStack>
  );
}

function ComparisonCell({
  value,
  isCurrentPlan,
}: {
  value: FeatureValue;
  isCurrentPlan: boolean;
}) {
  return (
    <InlineStack align="center" blockAlign="center">
      {typeof value === "string" ? (
        <Text
          as="p"
          variant="bodyLg"
          fontWeight={isCurrentPlan ? "semibold" : "regular"}
          alignment="center"
        >
          {value}
        </Text>
      ) : (
        <Icon
          source={value ? CheckCircleIcon : XCircleIcon}
          tone={value ? "success" : "subdued"}
        />
      )}
    </InlineStack>
  );
}

// ─── Plan card ────────────────────────────────────────────────────────────────

type PlanCardProps = {
  plan: (typeof PLANS_DATA)[keyof typeof PLANS_DATA];
  isAnnual: boolean;
  currentTier: string;
  onSubscribe: (planId: string, interval: string) => void;
  loadingPlan: string | null;
};

function PlanCard({
  plan,
  isAnnual,
  currentTier,
  onSubscribe,
  loadingPlan,
}: PlanCardProps) {
  const isCurrent = currentTier === plan.id;
  const isBestValue = "bestValue" in plan && plan.bestValue;

  const isUpgrade =
    !isCurrent &&
    plan.id !== "free" &&
    (TIER_ORDER[plan.id] ?? 0) > (TIER_ORDER[currentTier] ?? 0);

  const isDowngrade =
    !isCurrent &&
    plan.id !== "free" &&
    (TIER_ORDER[plan.id] ?? 0) < (TIER_ORDER[currentTier] ?? 0);

  const displayPrice = isAnnual ? plan.annualMonthlyPrice : plan.monthlyPrice;

  let buttonContent = "Start free trial";
  let buttonVariant: "primary" | "secondary" = "primary";

  if (isCurrent) {
    buttonContent = "Current plan";
    buttonVariant = "secondary";
  } else if (isUpgrade) {
    buttonContent = `Upgrade to ${plan.name}`;
    buttonVariant = "primary";
  } else if (isDowngrade) {
    buttonContent = `Switch to ${plan.name}`;
    buttonVariant = "secondary";
  }

  const handleClick = () => {
    onSubscribe(plan.id, isAnnual ? "annual" : "monthly");
  };

  const isThisLoading = loadingPlan === plan.id;

  return (
    <Box
      background="bg-surface"
      borderWidth="025"
      borderColor="border"
      borderRadius="300"
      padding="0"
      overflowX="hidden"
      overflowY="hidden"
    >
      {/* Top accent bar — blue for recommended plan */}
      <Box
        background={isBestValue && !isCurrent ? "bg-fill-info" : undefined}
        minHeight="4px"
      />

      <Box padding="500">
        <BlockStack gap="400">
          {/* Plan name + badges */}
          <BlockStack gap="100">
            <InlineStack gap="200" blockAlign="center" wrap={false}>
              <Text as="h3" variant="headingLg" fontWeight="bold">
                {plan.name}
              </Text>
              {isCurrent && <Badge tone="success">Active</Badge>}
              {isBestValue && !isCurrent && (
                <Badge tone="info-strong">Most popular</Badge>
              )}
            </InlineStack>
            <Text as="p" variant="bodyMd" tone="subdued">
              {plan.description}
            </Text>
          </BlockStack>

          {/* Price */}
          <BlockStack gap="050">
            <InlineStack gap="100" blockAlign="baseline" wrap={false}>
              <Text as="p" variant="heading2xl" fontWeight="bold">
                ${displayPrice}
              </Text>
              <Text as="p" variant="bodyMd" tone="subdued">
                /mo
              </Text>
            </InlineStack>
            <Text as="p" variant="bodyMd" tone="subdued">
              {isAnnual
                ? `$${plan.annualPrice} billed annually`
                : `or $${plan.annualMonthlyPrice}/mo billed annually`}
            </Text>
          </BlockStack>

          {/* CTA */}
          <Button
            variant={buttonVariant}
            onClick={handleClick}
            disabled={isCurrent}
            loading={isThisLoading}
            fullWidth
            size="large"
          >
            {buttonContent}
          </Button>

          <Divider />

          {/* Features */}
          <BlockStack gap="300">
            {plan.features.map((f) => (
              <PlanFeature key={f} feature={f} />
            ))}
          </BlockStack>
        </BlockStack>
      </Box>
    </Box>
  );
}

// ─── Page ─────────────────────────────────────────────────────────────────────

export default function PricingPage() {
  const { currentTier, billingInterval, planStatus } =
    useLoaderData<typeof loader>();
  const fetcher = useFetcher<typeof action>();
  const navigate = useNavigate();

  const [isAnnual, setIsAnnual] = useState(billingInterval === "annual");
  const [loadingPlan, setLoadingPlan] = useState<string | null>(null);
  const [cancelModalOpen, setCancelModalOpen] = useState(false);

  const fetcherData = fetcher.data;
  const isFetching = fetcher.state !== "idle";

  useEffect(() => {
    if (!isFetching) setLoadingPlan(null);
    if (fetcherData && "message" in fetcherData && fetcherData.message) {
      showToast(fetcherData.message);
    }
  }, [fetcherData, isFetching]);

  const actionError =
    fetcherData && "error" in fetcherData && fetcherData.error
      ? fetcherData.error
      : null;

  const handleSubscribe = useCallback(
    (planId: string, interval: string) => {
      setLoadingPlan(planId);
      const fd = new FormData();
      fd.set("intent", "subscribe");
      fd.set("planId", planId);
      fd.set("interval", interval);
      fetcher.submit(fd, { method: "POST" });
    },
    [fetcher],
  );

  const handleConfirmCancel = useCallback(() => {
    setCancelModalOpen(false);
    setLoadingPlan("cancel");
    const fd = new FormData();
    fd.set("intent", "cancel");
    fetcher.submit(fd, { method: "POST" });
  }, [fetcher]);

  const isFreeTier = currentTier === "free";

  return (
    <Page
      title="Pricing"
      subtitle="Choose the plan that's right for your store"
      backAction={{ onAction: () => navigate("/app") }}
    >
      <Box paddingBlockEnd="1600">
        <BlockStack gap="600">
          {/* Error banner */}
          {actionError && (
            <Banner tone="critical" title="Billing error">
              <Text as="p" variant="bodyMd">
                {actionError}
              </Text>
            </Banner>
          )}

          {/* Billing toggle */}
          <InlineStack align="center">
            <ButtonGroup variant="segmented">
              <Button
                pressed={!isAnnual}
                onClick={() => setIsAnnual(false)}
              >
                Monthly
              </Button>
              <Button
                pressed={isAnnual}
                onClick={() => setIsAnnual(true)}
              >
                Annual · Save up to 38%
              </Button>
            </ButtonGroup>
          </InlineStack>

          {/* Free plan — full-width card */}
          <Card padding="0">
            <Box padding="500">
              <BlockStack gap="400">
                {/* Top row: info + price + button */}
                <InlineGrid
                  columns={{ xs: 1, md: "1fr auto auto" }}
                  gap="400"
                  alignItems="center"
                >
                  <BlockStack gap="050">
                    <InlineStack gap="200" blockAlign="center" wrap={false}>
                      <Text as="h3" variant="headingLg" fontWeight="bold">
                        Free
                      </Text>
                      {isFreeTier && <Badge tone="success">Active</Badge>}
                    </InlineStack>
                    <Text as="p" variant="bodyMd" tone="subdued">
                      {PLANS_DATA.free.description}
                    </Text>
                  </BlockStack>

                  <InlineStack
                    gap="100"
                    blockAlign="baseline"
                    wrap={false}
                  >
                    <Text as="p" variant="heading2xl" fontWeight="bold">
                      $0
                    </Text>
                    <Text as="p" variant="bodyMd" tone="subdued">
                      forever
                    </Text>
                  </InlineStack>

                  <Box minWidth="180px">
                    {isFreeTier ? (
                      <Button
                        variant="secondary"
                        disabled
                        fullWidth
                        size="large"
                      >
                        Current plan
                      </Button>
                    ) : (
                      <Button
                        variant="plain"
                        tone="critical"
                        onClick={() => setCancelModalOpen(true)}
                        loading={loadingPlan === "cancel"}
                      >
                        Downgrade to Free
                      </Button>
                    )}
                  </Box>
                </InlineGrid>

                <Divider />

                {/* Features */}
                <InlineGrid columns={{ xs: 1, sm: 3 }} gap="300">
                  {PLANS_DATA.free.features.map((f) => (
                    <PlanFeature key={f} feature={f} />
                  ))}
                </InlineGrid>
              </BlockStack>
            </Box>
          </Card>

          {/* Paid plan cards — 2 columns */}
          <InlineGrid columns={{ xs: 1, md: 2 }} gap="400">
            <PlanCard
              plan={PLANS_DATA.starter}
              isAnnual={isAnnual}
              currentTier={currentTier}
              onSubscribe={handleSubscribe}
              loadingPlan={loadingPlan}
            />
            <PlanCard
              plan={PLANS_DATA.pro}
              isAnnual={isAnnual}
              currentTier={currentTier}
              onSubscribe={handleSubscribe}
              loadingPlan={loadingPlan}
            />
          </InlineGrid>

          {/* Trial note */}
          <Text as="p" variant="bodyMd" tone="subdued" alignment="center">
            All paid plans include a 7-day free trial. No credit card charged
            until the trial ends.
          </Text>

          {/* Feature comparison table */}
          <BlockStack gap="300">
            <Text as="h2" variant="headingLg" alignment="center">
              Full Feature Comparison
            </Text>

            <Card padding="0">
              <BlockStack gap="0">
                {/* Header */}
                <Box padding="500" paddingBlockEnd="400">
                  <InlineGrid
                    columns="4fr 2fr 2fr 2fr"
                    gap="300"
                    alignItems="end"
                  >
                    <Text
                      as="p"
                      variant="bodyMd"
                      fontWeight="semibold"
                      tone="subdued"
                    >
                      Feature
                    </Text>
                    {PLAN_ORDER.map((id) => {
                      const plan = PLANS_DATA[id];
                      const isCurrentCol = currentTier === id;
                      return (
                        <BlockStack key={id} gap="100" inlineAlign="center">
                          <Text
                            as="p"
                            variant="headingMd"
                            fontWeight="bold"
                            alignment="center"
                          >
                            {plan.name}
                          </Text>
                          <Text
                            as="p"
                            variant="bodyMd"
                            tone={isCurrentCol ? "success" : "subdued"}
                            fontWeight={
                              isCurrentCol ? "semibold" : "regular"
                            }
                            alignment="center"
                          >
                            {isCurrentCol
                              ? "Current"
                              : plan.monthlyPrice === 0
                                ? "Free"
                                : isAnnual
                                  ? `$${plan.annualMonthlyPrice}/mo`
                                  : `$${plan.monthlyPrice}/mo`}
                          </Text>
                        </BlockStack>
                      );
                    })}
                  </InlineGrid>
                </Box>

                <Divider />

                {/* Rows */}
                {FEATURE_ROWS.map((row, i) => (
                  <Box key={row.label}>
                    <Box
                      padding="500"
                      paddingBlock="400"
                      background={
                        i % 2 === 0 ? "bg-surface" : "bg-surface-secondary"
                      }
                    >
                      <InlineGrid
                        columns="4fr 2fr 2fr 2fr"
                        gap="300"
                        alignItems="center"
                      >
                        <Text as="p" variant="bodyLg">
                          {row.label}
                        </Text>
                        {PLAN_ORDER.map((id) => (
                          <ComparisonCell
                            key={id}
                            value={row[id]}
                            isCurrentPlan={currentTier === id}
                          />
                        ))}
                      </InlineGrid>
                    </Box>
                  </Box>
                ))}
              </BlockStack>
            </Card>
          </BlockStack>
        </BlockStack>
      </Box>

      {/* Downgrade confirmation modal */}
      <Modal
        open={cancelModalOpen}
        onClose={() => setCancelModalOpen(false)}
        title="Downgrade to Free plan?"
        primaryAction={{
          content: "Yes, downgrade",
          destructive: true,
          onAction: handleConfirmCancel,
          loading: loadingPlan === "cancel",
        }}
        secondaryActions={[
          {
            content: "Keep current plan",
            onAction: () => setCancelModalOpen(false),
          },
        ]}
      >
        <Modal.Section>
          <BlockStack gap="400">
            <Text as="p" variant="bodyMd">
              Downgrading to Free will immediately remove access to:
            </Text>
            <BlockStack gap="200">
              {[
                "Extra quizzes — limited to 1 active quiz",
                "Unlimited responses — limited to 100/month",
                "Email integrations (Klaviyo, Omnisend, Webhooks)",
                "Advanced & full analytics",
                "A/B testing",
                "AI auto-mapping",
                "Branding removal (QuizSnap branding will show)",
                "Priority support",
              ].map((item) => (
                <InlineStack
                  key={item}
                  gap="200"
                  blockAlign="start"
                  wrap={false}
                >
                  <Box>
                    <Icon source={XCircleIcon} tone="critical" />
                  </Box>
                  <Text as="p" variant="bodyMd">
                    {item}
                  </Text>
                </InlineStack>
              ))}
            </BlockStack>
            <Banner tone="warning">
              <Text as="p" variant="bodyMd">
                Your quiz data and responses will remain saved. If you have
                more than 1 quiz, extras will be paused until you upgrade
                again.
              </Text>
            </Banner>
          </BlockStack>
        </Modal.Section>
      </Modal>
    </Page>
  );
}

// ─── Error boundary ──────────────────────────────────────────────────────────

export function ErrorBoundary() {
  return boundary.error(useRouteError());
}

// ─── Skeleton ────────────────────────────────────────────────────────────────

export function HydrateFallback() {
  return (
    <SkeletonPage title="Pricing">
      <BlockStack gap="600">
        <Card>
          <BlockStack gap="400">
            <SkeletonDisplayText size="small" />
            <SkeletonBodyText lines={2} />
          </BlockStack>
        </Card>
        <InlineGrid columns={2} gap="400">
          {[0, 1].map((i) => (
            <Card key={i}>
              <BlockStack gap="400">
                <SkeletonDisplayText size="small" />
                <SkeletonDisplayText size="large" />
                <SkeletonBodyText lines={6} />
              </BlockStack>
            </Card>
          ))}
        </InlineGrid>
        <Card>
          <SkeletonBodyText lines={8} />
        </Card>
      </BlockStack>
    </SkeletonPage>
  );
}

export const headers: HeadersFunction = (headersArgs) => {
  return boundary.headers(headersArgs);
};

