import { showToast } from "../utils/toast";
import type {
  ActionFunctionArgs,
  HeadersFunction,
  LoaderFunctionArgs,
} from "react-router";
import {
  useLoaderData,
  useActionData,
  useNavigation,
  Form,
} from "react-router";
import {
  Page,
  Card,
  Text,
  InlineStack,
  BlockStack,
  Button,
  Badge,
  Divider,
  Banner,
  ProgressBar,
  Icon,
  Box,
  InlineGrid,
  SkeletonPage,
  SkeletonBodyText,
  SkeletonDisplayText,
  Collapsible,
} from "@shopify/polaris";
import {
  CheckIcon,
  XSmallIcon,
  StarFilledIcon,
  ChevronDownIcon,
  ChevronUpIcon,
} from "@shopify/polaris-icons";
import { useEffect, useState, useCallback } from "react";
import { data } from "react-router";
import { authenticate } from "../shopify.server";
import { boundary } from "@shopify/shopify-app-react-router/server";
import db from "../db.server";

// ── Plan data matching Notion spec ───────────────────────────────────────────

interface PlanConfig {
  id: string;
  name: string;
  price: number;
  priceSuffix: string;
  description: string;
  badge: string | null;
  badgeTone: "success" | "info" | "attention" | undefined;
  quizLimit: number;
  quizLimitLabel: string;
  responseLimit: number;
  responseLimitLabel: string;
  features: Array<{ text: string; included: boolean }>;
  highlight: boolean;
}

const PLANS: PlanConfig[] = [
  {
    id: "free",
    name: "Free",
    price: 0,
    priceSuffix: "/month",
    description: "Get started with quizzes — no credit card needed",
    badge: null,
    badgeTone: undefined,
    quizLimit: 1,
    quizLimitLabel: "1",
    responseLimit: 100,
    responseLimitLabel: "100",
    features: [
      { text: "1 active quiz", included: true },
      { text: "100 responses/month", included: true },
      { text: "All question types", included: true },
      { text: "Basic analytics", included: true },
      { text: "QuizSnap branding", included: true },
      { text: "Email integrations", included: false },
      { text: "Remove branding", included: false },
      { text: "A/B testing", included: false },
      { text: "Priority support", included: false },
    ],
    highlight: false,
  },
  {
    id: "starter",
    name: "Starter",
    price: 29,
    priceSuffix: "/month",
    description: "For growing stores that want better engagement",
    badge: "Most popular",
    badgeTone: "success",
    quizLimit: 5,
    quizLimitLabel: "5",
    responseLimit: 999999,
    responseLimitLabel: "Unlimited",
    features: [
      { text: "5 active quizzes", included: true },
      { text: "Unlimited responses", included: true },
      { text: "All question types", included: true },
      { text: "Advanced analytics", included: true },
      { text: "Remove branding", included: true },
      { text: "Klaviyo + Webhooks", included: true },
      { text: "Email capture", included: true },
      { text: "A/B testing", included: false },
      { text: "Priority support", included: false },
    ],
    highlight: true,
  },
  {
    id: "pro",
    name: "Pro",
    price: 79,
    priceSuffix: "/month",
    description: "For brands that rely on personalisation at scale",
    badge: "Best value",
    badgeTone: "info",
    quizLimit: 999,
    quizLimitLabel: "Unlimited",
    responseLimit: 999999,
    responseLimitLabel: "Unlimited",
    features: [
      { text: "Unlimited quizzes", included: true },
      { text: "Unlimited responses", included: true },
      { text: "All question types", included: true },
      { text: "Full analytics suite", included: true },
      { text: "Remove branding", included: true },
      { text: "All integrations", included: true },
      { text: "AI auto-mapping", included: true },
      { text: "A/B testing", included: true },
      { text: "Shopify Flow trigger", included: true },
      { text: "Priority support", included: true },
    ],
    highlight: false,
  },
];

type PlanId = "free" | "starter" | "pro";

// ── Feature comparison table data ────────────────────────────────────────────

const COMPARISON_FEATURES = [
  { label: "Active quizzes", free: "1", starter: "5", pro: "Unlimited" },
  {
    label: "Monthly responses",
    free: "100",
    starter: "Unlimited",
    pro: "Unlimited",
  },
  { label: "Question types", free: "All", starter: "All", pro: "All" },
  { label: "Analytics", free: "Basic", starter: "Advanced", pro: "Full suite" },
  { label: "QuizSnap branding", free: "Shown", starter: "Hidden", pro: "Hidden" },
  { label: "Email capture", free: false, starter: true, pro: true },
  { label: "Klaviyo integration", free: false, starter: true, pro: true },
  { label: "Webhook integration", free: false, starter: true, pro: true },
  { label: "Omnisend integration", free: false, starter: false, pro: true },
  { label: "Shopify Flow trigger", free: false, starter: false, pro: true },
  { label: "A/B testing", free: false, starter: false, pro: true },
  { label: "AI auto-mapping", free: false, starter: false, pro: true },
  { label: "CSV export", free: false, starter: false, pro: true },
  { label: "Priority support", free: false, starter: false, pro: true },
];

// ── FAQ data ─────────────────────────────────────────────────────────────────

const FAQ_ITEMS = [
  {
    question: "How does the 7-day free trial work?",
    answer:
      "When you upgrade to Starter or Pro, you get 7 days to try the full plan at no charge. You won't be billed until the trial ends. Cancel anytime during the trial and you'll return to the Free plan with no charges.",
  },
  {
    question: "Can I change plans at any time?",
    answer:
      "Yes! Upgrade or downgrade whenever you like. When you upgrade, you get access immediately. When you downgrade, your current features stay active until the end of the billing cycle.",
  },
  {
    question: "What counts as a response?",
    answer:
      "A response is counted each time a shopper completes your quiz (reaches the results page). Partial abandonments do not count. On the Free plan, you get 100 responses per calendar month — the counter resets on the 1st.",
  },
  {
    question: "What happens if I hit my response limit?",
    answer:
      "Your quiz stays live but stops recording new responses until the counter resets next month. Upgrade anytime to unlock more (or unlimited) responses with no data loss.",
  },
  {
    question: "How does billing work with Shopify?",
    answer:
      "All charges go through Shopify's billing system — the same invoice as your Shopify subscription. No separate credit card required. You can manage your subscription from this page or from the Shopify admin.",
  },
];

// ── Loader ───────────────────────────────────────────────────────────────────

export const loader = async ({ request }: LoaderFunctionArgs) => {
  const { session } = await authenticate.admin(request);

  try {
    const startOfMonth = new Date();
    startOfMonth.setDate(1);
    startOfMonth.setHours(0, 0, 0, 0);

    const [sub, quizCount, responseCount] = await Promise.all([
      db.subscription.findUnique({ where: { shop: session.shop } }),
      db.quiz.count({
        where: { shop: session.shop, status: { not: "archived" } },
      }),
      db.quizResponse.count({
        where: {
          shop: session.shop,
          createdAt: { gte: startOfMonth },
        },
      }),
    ]);

    return {
      currentPlan: (sub?.planId ?? "free") as PlanId,
      planStatus: sub?.status ?? "active",
      quizCount,
      responseCount,
      trialEndsAt: sub?.trialEndsAt?.toISOString() ?? null,
    };
  } catch {
    return {
      currentPlan: "free" as PlanId,
      planStatus: "active",
      quizCount: 0,
      responseCount: 0,
      trialEndsAt: null,
    };
  }
};

// ── Action ───────────────────────────────────────────────────────────────────

export const action = async ({ request }: ActionFunctionArgs) => {
  const { session } = await authenticate.admin(request);
  const formData = await request.formData();
  const planId = String(formData.get("planId") ?? "") as PlanId;

  const validPlans: PlanId[] = ["free", "starter", "pro"];
  if (!validPlans.includes(planId)) {
    return data({ error: "Invalid plan selected" }, { status: 400 });
  }

  try {
    const plan = PLANS.find((p) => p.id === planId);
    if (!plan) {
      return data({ error: "Plan not found" }, { status: 400 });
    }

    await db.subscription.upsert({
      where: { shop: session.shop },
      create: {
        shop: session.shop,
        planId,
        status: "active",
        quizLimit: plan.quizLimit,
        responseLimit: plan.responseLimit,
        trialEndsAt:
          planId !== "free"
            ? new Date(Date.now() + 7 * 24 * 60 * 60 * 1000)
            : null,
      },
      update: {
        planId,
        status: "active",
        quizLimit: plan.quizLimit,
        responseLimit: plan.responseLimit,
      },
    });

    const message =
      planId === "free"
        ? "Downgraded to Free plan"
        : `Upgraded to ${plan.name} — 7-day free trial started!`;

    return { success: true, message };
  } catch {
    return data(
      { error: "Failed to update plan. Please try again." },
      { status: 500 },
    );
  }
};

// ── Helper components ────────────────────────────────────────────────────────

function FeatureRow({
  text,
  included,
}: {
  text: string;
  included: boolean;
}) {
  return (
    <InlineStack gap="200" blockAlign="center" wrap={false}>
      <div
        style={{
          width: 20,
          height: 20,
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          flexShrink: 0,
        }}
      >
        {included ? (
          <Icon source={CheckIcon} tone="success" />
        ) : (
          <Icon source={XSmallIcon} tone="subdued" />
        )}
      </div>
      <Text
        as="span"
        variant="bodyMd"
        tone={included ? undefined : "subdued"}
      >
        {text}
      </Text>
    </InlineStack>
  );
}

function UsageMeter({
  label,
  current,
  limit,
  limitLabel,
}: {
  label: string;
  current: number;
  limit: number;
  limitLabel: string;
}) {
  const isUnlimited = limit >= 999999;
  const percentage = isUnlimited
    ? 0
    : limit > 0
      ? Math.min((current / limit) * 100, 100)
      : 0;
  const isNearLimit = !isUnlimited && percentage >= 80;
  const isAtLimit = !isUnlimited && percentage >= 100;

  return (
    <BlockStack gap="200">
      <InlineStack align="space-between">
        <Text as="p" variant="bodyMd" fontWeight="semibold">
          {label}
        </Text>
        <Text
          as="p"
          variant="bodyMd"
          tone={isAtLimit ? "critical" : isNearLimit ? "caution" : "subdued"}
        >
          {current.toLocaleString()} / {limitLabel}
        </Text>
      </InlineStack>
      {!isUnlimited && (
        <ProgressBar
          progress={percentage}
          tone={isAtLimit ? "critical" : isNearLimit ? "highlight" : "primary"}
          size="small"
        />
      )}
      {isUnlimited && (
        <div
          style={{
            height: 4,
            borderRadius: 2,
            background: "var(--p-color-bg-fill-success)",
          }}
        />
      )}
    </BlockStack>
  );
}

// ── Main component ───────────────────────────────────────────────────────────

export default function BillingPage() {
  const { currentPlan, planStatus, quizCount, responseCount, trialEndsAt } =
    useLoaderData<typeof loader>();
  const actionData = useActionData<typeof action>();
  const navigation = useNavigation();
  const isUpdating = navigation.state === "submitting";
  const submittingPlanId = navigation.formData?.get("planId") as string | null;

  const [openFaq, setOpenFaq] = useState<number | null>(null);
  const [showComparison, setShowComparison] = useState(false);

  const toggleFaq = useCallback(
    (index: number) =>
      setOpenFaq((prev) => (prev === index ? null : index)),
    [],
  );
  const toggleComparison = useCallback(
    () => setShowComparison((prev) => !prev),
    [],
  );

  useEffect(() => {
    if (actionData && "success" in actionData && actionData.success) {
      showToast(actionData.message ?? "Plan updated!");
    }
    if (actionData && "error" in actionData && actionData.error) {
      showToast(actionData.error, { isError: true });
    }
  }, [actionData]);

  const currentPlanData =
    PLANS.find((p) => p.id === currentPlan) ?? PLANS[0];
  const planIndex = PLANS.findIndex((p) => p.id === currentPlan);

  const trialDaysLeft = trialEndsAt
    ? Math.max(
        0,
        Math.ceil(
          (new Date(trialEndsAt).getTime() - Date.now()) /
            (1000 * 60 * 60 * 24),
        ),
      )
    : 0;

  return (
    <Page title="Plans & Billing" subtitle="Choose the right plan for your store">
      <BlockStack gap="600">
        {/* ── Error banner ──────────────────────────────────── */}
        {actionData && "error" in actionData && actionData.error && (
          <Banner tone="critical" title="Update failed">
            <p>{actionData.error}</p>
          </Banner>
        )}

        {/* ── Trial banner ──────────────────────────────────── */}
        {trialEndsAt && trialDaysLeft > 0 && (
          <Banner tone="info" title={`${trialDaysLeft} day${trialDaysLeft !== 1 ? "s" : ""} left in your trial`}>
            <p>
              Your free trial of the {currentPlanData.name} plan ends on{" "}
              {new Date(trialEndsAt).toLocaleDateString("en-US", {
                month: "long",
                day: "numeric",
                year: "numeric",
              })}
              . You won't be charged until the trial ends.
            </p>
          </Banner>
        )}

        {/* ── Usage limit warning ───────────────────────────── */}
        {currentPlan === "free" &&
          responseCount >= 80 &&
          responseCount < 100 && (
            <Banner tone="warning" title="Approaching response limit">
              <p>
                You've used {responseCount} of 100 responses this month.
                Upgrade to Starter for unlimited responses.
              </p>
            </Banner>
          )}

        {currentPlan === "free" && responseCount >= 100 && (
          <Banner tone="critical" title="Response limit reached">
            <p>
              You've reached your 100 response limit for this month. New
              responses won't be recorded until next month. Upgrade now to
              continue collecting responses.
            </p>
          </Banner>
        )}

        {/* ── Current plan + usage card ─────────────────────── */}
        <Card>
          <BlockStack gap="400">
            <InlineStack align="space-between" blockAlign="center">
              <InlineStack gap="300" blockAlign="center">
                <Text as="h2" variant="headingMd">
                  Current plan
                </Text>
                <Badge
                  tone={
                    currentPlan === "free"
                      ? undefined
                      : currentPlan === "starter"
                        ? "success"
                        : "info"
                  }
                >
                  {currentPlanData.name}
                </Badge>
                {planStatus === "frozen" && (
                  <Badge tone="warning">Frozen</Badge>
                )}
              </InlineStack>
              <Text as="p" variant="headingLg" fontWeight="bold">
                ${currentPlanData.price}
                <Text as="span" variant="bodySm" tone="subdued">
                  {currentPlanData.priceSuffix}
                </Text>
              </Text>
            </InlineStack>

            <Divider />

            <InlineGrid columns={2} gap="400">
              <UsageMeter
                label="Active quizzes"
                current={quizCount}
                limit={currentPlanData.quizLimit}
                limitLabel={currentPlanData.quizLimitLabel}
              />
              <UsageMeter
                label="Responses this month"
                current={responseCount}
                limit={currentPlanData.responseLimit}
                limitLabel={currentPlanData.responseLimitLabel}
              />
            </InlineGrid>
          </BlockStack>
        </Card>

        {/* ── Plan cards grid ───────────────────────────────── */}
        <BlockStack gap="300">
          <Text as="h2" variant="headingLg">
            Choose your plan
          </Text>
          <Text as="p" variant="bodyMd" tone="subdued">
            All paid plans include a 7-day free trial. Cancel anytime.
          </Text>
        </BlockStack>

        <InlineGrid columns={3} gap="400">
          {PLANS.map((plan, index) => {
            const isCurrent = plan.id === currentPlan;
            const isUpgrade = index > planIndex;
            const isDowngrade = index < planIndex;
            const isThisSubmitting =
              isUpdating && submittingPlanId === plan.id;

            let ctaText = "Current plan";
            let ctaVariant: "primary" | "secondary" | "tertiary" =
              "secondary";
            let ctaTone: "critical" | undefined;

            if (!isCurrent) {
              if (isUpgrade) {
                ctaText =
                  plan.price === 0
                    ? "Downgrade to Free"
                    : `Start free trial`;
                ctaVariant = plan.highlight ? "primary" : "secondary";
              } else if (isDowngrade) {
                ctaText =
                  plan.id === "free" ? "Downgrade to Free" : `Downgrade`;
                ctaTone = "critical";
              }
            }

            return (
              <div
                key={plan.id}
                style={{
                  border: plan.highlight
                    ? "2px solid var(--p-color-border-emphasis)"
                    : isCurrent
                      ? "2px solid var(--p-color-border-success)"
                      : "1px solid var(--p-color-border)",
                  borderRadius: "var(--p-border-radius-300)",
                  padding: "20px",
                  position: "relative",
                  background: "var(--p-color-bg-surface)",
                  display: "flex",
                  flexDirection: "column",
                }}
              >
                {/* Badge */}
                {plan.badge && (
                  <div
                    style={{
                      position: "absolute",
                      top: -12,
                      left: "50%",
                      transform: "translateX(-50%)",
                      whiteSpace: "nowrap",
                    }}
                  >
                    <Badge tone={plan.badgeTone}>{plan.badge}</Badge>
                  </div>
                )}

                {isCurrent && !plan.badge && (
                  <div
                    style={{
                      position: "absolute",
                      top: -12,
                      left: "50%",
                      transform: "translateX(-50%)",
                      whiteSpace: "nowrap",
                    }}
                  >
                    <Badge tone="success">Current plan</Badge>
                  </div>
                )}

                <BlockStack gap="400">
                  {/* Plan name + price */}
                  <BlockStack gap="200">
                    <Text as="h3" variant="headingMd" fontWeight="bold">
                      {plan.name}
                    </Text>
                    <InlineStack gap="100" blockAlign="end">
                      <Text
                        as="span"
                        variant="heading2xl"
                        fontWeight="bold"
                      >
                        ${plan.price}
                      </Text>
                      <Text as="span" variant="bodyMd" tone="subdued">
                        {plan.priceSuffix}
                      </Text>
                    </InlineStack>
                    <Text as="p" variant="bodySm" tone="subdued">
                      {plan.description}
                    </Text>
                  </BlockStack>

                  <Divider />

                  {/* Feature list */}
                  <BlockStack gap="200">
                    {plan.features.map((feature) => (
                      <FeatureRow
                        key={feature.text}
                        text={feature.text}
                        included={feature.included}
                      />
                    ))}
                  </BlockStack>

                  {/* CTA button — pushed to bottom */}
                  <div style={{ marginTop: "auto", paddingTop: 8 }}>
                    <Form method="post">
                      <input
                        type="hidden"
                        name="planId"
                        value={plan.id}
                      />
                      <Button
                        submit
                        variant={isCurrent ? "tertiary" : ctaVariant}
                        disabled={isCurrent || isUpdating}
                        loading={isThisSubmitting}
                        fullWidth
                        tone={ctaTone}
                        size="large"
                      >
                        {isCurrent ? "Current plan" : ctaText}
                      </Button>
                    </Form>
                  </div>
                </BlockStack>
              </div>
            );
          })}
        </InlineGrid>

        {/* ── Feature comparison table ──────────────────────── */}
        <Card>
          <BlockStack gap="400">
            <InlineStack align="space-between" blockAlign="center">
              <Text as="h2" variant="headingMd">
                Compare all features
              </Text>
              <Button
                onClick={toggleComparison}
                variant="plain"
                icon={showComparison ? ChevronUpIcon : ChevronDownIcon}
              >
                {showComparison ? "Hide" : "Show"} comparison
              </Button>
            </InlineStack>

            <Collapsible
              open={showComparison}
              id="feature-comparison"
              transition={{
                duration: "300ms",
                timingFunction: "ease-in-out",
              }}
            >
              <Box paddingBlockStart="200">
                {/* Table header */}
                <div
                  style={{
                    display: "grid",
                    gridTemplateColumns: "1fr 120px 120px 120px",
                    gap: "0",
                    borderBottom:
                      "2px solid var(--p-color-border)",
                    paddingBottom: 8,
                    marginBottom: 4,
                  }}
                >
                  <Text as="span" variant="bodySm" fontWeight="bold">
                    Feature
                  </Text>
                  <Text
                    as="span"
                    variant="bodySm"
                    fontWeight="bold"
                    alignment="center"
                  >
                    Free
                  </Text>
                  <Text
                    as="span"
                    variant="bodySm"
                    fontWeight="bold"
                    alignment="center"
                  >
                    Starter
                  </Text>
                  <Text
                    as="span"
                    variant="bodySm"
                    fontWeight="bold"
                    alignment="center"
                  >
                    Pro
                  </Text>
                </div>

                {/* Table rows */}
                {COMPARISON_FEATURES.map((row, i) => (
                  <div
                    key={row.label}
                    style={{
                      display: "grid",
                      gridTemplateColumns: "1fr 120px 120px 120px",
                      gap: "0",
                      padding: "8px 0",
                      borderBottom:
                        i < COMPARISON_FEATURES.length - 1
                          ? "1px solid var(--p-color-border-secondary)"
                          : "none",
                      alignItems: "center",
                    }}
                  >
                    <Text as="span" variant="bodySm">
                      {row.label}
                    </Text>
                    {(["free", "starter", "pro"] as const).map((planKey) => {
                      const value = row[planKey];
                      return (
                        <div
                          key={planKey}
                          style={{
                            textAlign: "center",
                            display: "flex",
                            justifyContent: "center",
                          }}
                        >
                          {typeof value === "boolean" ? (
                            value ? (
                              <Icon source={CheckIcon} tone="success" />
                            ) : (
                              <Icon source={XSmallIcon} tone="subdued" />
                            )
                          ) : (
                            <Text as="span" variant="bodySm">
                              {value}
                            </Text>
                          )}
                        </div>
                      );
                    })}
                  </div>
                ))}
              </Box>
            </Collapsible>
          </BlockStack>
        </Card>

        {/* ── FAQ section ───────────────────────────────────── */}
        <Card>
          <BlockStack gap="400">
            <Text as="h2" variant="headingMd">
              Frequently asked questions
            </Text>

            {FAQ_ITEMS.map((item, index) => (
              <div key={index}>
                {index > 0 && <Divider />}
                <div style={{ paddingTop: index > 0 ? 12 : 0 }}>
                  <BlockStack gap="200">
                    <Button
                      onClick={() => toggleFaq(index)}
                      variant="plain"
                      textAlign="start"
                      fullWidth
                      icon={
                        openFaq === index
                          ? ChevronUpIcon
                          : ChevronDownIcon
                      }
                    >
                      {item.question}
                    </Button>
                    <Collapsible
                      open={openFaq === index}
                      id={`faq-${index}`}
                      transition={{
                        duration: "200ms",
                        timingFunction: "ease-in-out",
                      }}
                    >
                      <Box paddingInlineStart="600" paddingBlockEnd="200">
                        <Text as="p" variant="bodyMd" tone="subdued">
                          {item.answer}
                        </Text>
                      </Box>
                    </Collapsible>
                  </BlockStack>
                </div>
              </div>
            ))}
          </BlockStack>
        </Card>

        {/* ── Footer guarantees ─────────────────────────────── */}
        <Box paddingBlockEnd="400">
          <InlineStack align="center" gap="600">
            <InlineStack gap="100" blockAlign="center">
              <Icon source={CheckIcon} tone="success" />
              <Text as="span" variant="bodySm" tone="subdued">
                7-day free trial
              </Text>
            </InlineStack>
            <InlineStack gap="100" blockAlign="center">
              <Icon source={CheckIcon} tone="success" />
              <Text as="span" variant="bodySm" tone="subdued">
                Cancel anytime
              </Text>
            </InlineStack>
            <InlineStack gap="100" blockAlign="center">
              <Icon source={CheckIcon} tone="success" />
              <Text as="span" variant="bodySm" tone="subdued">
                Billed through Shopify
              </Text>
            </InlineStack>
            <InlineStack gap="100" blockAlign="center">
              <Icon source={StarFilledIcon} tone="success" />
              <Text as="span" variant="bodySm" tone="subdued">
                Prices in USD
              </Text>
            </InlineStack>
          </InlineStack>
        </Box>
      </BlockStack>
    </Page>
  );
}

// ── Skeleton loading state ───────────────────────────────────────────────────

export function HydrateFallback() {
  return (
    <SkeletonPage title="Plans & Billing">
      <BlockStack gap="600">
        <Card>
          <BlockStack gap="400">
            <SkeletonDisplayText size="small" />
            <SkeletonBodyText lines={2} />
          </BlockStack>
        </Card>
        <InlineGrid columns={3} gap="400">
          {[0, 1, 2].map((i) => (
            <Card key={i}>
              <BlockStack gap="400">
                <SkeletonDisplayText size="small" />
                <SkeletonDisplayText size="large" />
                <SkeletonBodyText lines={6} />
              </BlockStack>
            </Card>
          ))}
        </InlineGrid>
        <Card>
          <SkeletonBodyText lines={4} />
        </Card>
      </BlockStack>
    </SkeletonPage>
  );
}

export const headers: HeadersFunction = (headersArgs) => {
  return boundary.headers(headersArgs);
};

