import { useCallback } from "react";
import type {
  ActionFunctionArgs,
  HeadersFunction,
  LoaderFunctionArgs,
} from "react-router";
import { useLoaderData, useNavigate } from "react-router";
import {
  Page,
  Layout,
  Card,
  Text,
  InlineStack,
  BlockStack,
  Banner,
  ProgressBar,
  List,
  IndexTable,
  Badge,
  Button,
  Box,
  Divider,
  InlineGrid,
  EmptyState,
  useIndexResourceState,
  SkeletonPage,
  SkeletonBodyText,
  SkeletonDisplayText,
} from "@shopify/polaris";
import { authenticate } from "../shopify.server";
import { boundary } from "@shopify/shopify-app-react-router/server";
import { getDashboardStats } from "../services/quiz.server";

// ─── Types ───────────────────────────────────────────────────────────────────

interface StatMetric {
  value: number;
  formatted: string;
  trend: string;
  up: boolean;
}

interface QuizRow {
  id: string;
  title: string;
  status: string;
  completions: number;
  createdAt: Date | string;
}

interface DashboardData {
  revenue: StatMetric;
  completions: StatMetric;
  emailsCaptured: StatMetric;
  quizzes: QuizRow[];
  activeQuizCount: number;
}

// ─── Constants ───────────────────────────────────────────────────────────────

type BadgeTone = "success" | "attention" | "warning" | undefined;

const STATUS_TONE: Record<string, BadgeTone> = {
  active: "success",
  draft: "attention",
  paused: "warning",
  archived: undefined,
};

const SETUP_STEPS = [
  { label: "Create your first quiz", key: "create" },
  { label: "Map products to answers", key: "map" },
  { label: "Publish your quiz", key: "publish" },
];

const EMPTY_STATS: DashboardData = {
  revenue: { value: 0, formatted: "$0.00", trend: "0%", up: true },
  completions: { value: 0, formatted: "0", trend: "0%", up: true },
  emailsCaptured: { value: 0, formatted: "0", trend: "0%", up: true },
  quizzes: [],
  activeQuizCount: 0,
};

// ─── Sparkline mini-bar colors ───────────────────────────────────────────────

const SPARKLINE_COLORS = {
  green: [
    "rgba(38, 132, 80, 0.2)",
    "rgba(38, 132, 80, 0.3)",
    "rgba(38, 132, 80, 0.4)",
    "rgba(38, 132, 80, 0.5)",
    "rgba(38, 132, 80, 0.6)",
    "rgba(38, 132, 80, 0.8)",
    "rgba(38, 132, 80, 1)",
  ],
  blue: [
    "rgba(48, 100, 180, 0.15)",
    "rgba(48, 100, 180, 0.2)",
    "rgba(48, 100, 180, 0.3)",
    "rgba(48, 100, 180, 0.45)",
    "rgba(48, 100, 180, 0.6)",
    "rgba(48, 100, 180, 0.8)",
    "rgba(48, 100, 180, 1)",
  ],
  violet: [
    "rgba(115, 80, 180, 0.15)",
    "rgba(115, 80, 180, 0.25)",
    "rgba(115, 80, 180, 0.35)",
    "rgba(115, 80, 180, 0.45)",
    "rgba(115, 80, 180, 0.55)",
    "rgba(115, 80, 180, 0.7)",
    "rgba(115, 80, 180, 0.85)",
  ],
  amber: [
    "rgba(185, 137, 0, 0.15)",
    "rgba(185, 137, 0, 0.25)",
    "rgba(185, 137, 0, 0.35)",
    "rgba(185, 137, 0, 0.5)",
    "rgba(185, 137, 0, 0.65)",
    "rgba(185, 137, 0, 0.8)",
    "rgba(185, 137, 0, 1)",
  ],
};

// Heights simulate relative daily values (7 days)
const SPARKLINE_HEIGHTS = {
  green: [12, 10, 16, 14, 18, 22, 20],
  blue: [8, 10, 12, 14, 16, 20, 24],
  violet: [14, 12, 16, 14, 18, 16, 20],
  amber: [10, 8, 14, 12, 18, 22, 24],
};

// ─── Loader / Action ─────────────────────────────────────────────────────────

export const loader = async ({ request }: LoaderFunctionArgs) => {
  const { session } = await authenticate.admin(request);
  try {
    const dashboardData = await getDashboardStats(session.shop);
    return { data: dashboardData };
  } catch {
    return { data: EMPTY_STATS };
  }
};

export const action = async ({ request }: ActionFunctionArgs) => {
  await authenticate.admin(request);
  return null;
};

// ─── Sparkline bars component ────────────────────────────────────────────────

function SparklineBars({
  colorKey,
}: {
  colorKey: keyof typeof SPARKLINE_COLORS;
}) {
  const colors = SPARKLINE_COLORS[colorKey];
  const heights = SPARKLINE_HEIGHTS[colorKey];

  return (
    <div
      style={{
        display: "flex",
        alignItems: "flex-end",
        gap: 3,
        height: 28,
        paddingTop: 4,
      }}
    >
      {colors.map((color, i) => (
        <div
          key={i}
          style={{
            width: 14,
            height: heights[i],
            borderRadius: 2,
            background: color,
          }}
        />
      ))}
    </div>
  );
}

// ─── Statistics Card component ───────────────────────────────────────────────

function StatCard({
  label,
  value,
  trendText,
  trendTone,
  borderColor,
  sparklineColor,
}: {
  label: string;
  value: string;
  trendText: string;
  trendTone: "success" | "critical" | "subdued";
  borderColor: string;
  sparklineColor: keyof typeof SPARKLINE_COLORS;
}) {
  return (
    <div
      style={{
        background: "var(--p-color-bg-surface)",
        borderRadius: "var(--p-border-radius-300)",
        border: "1px solid var(--p-color-border)",
        overflow: "hidden",
      }}
    >
      {/* Colored top border */}
      <div
        style={{
          height: 4,
          background: borderColor,
          borderRadius: "var(--p-border-radius-300) var(--p-border-radius-300) 0 0",
        }}
      />

      <div style={{ padding: "16px" }}>
        <BlockStack gap="200">
          {/* Big value */}
          <Text as="p" variant="headingXl" fontWeight="bold">
            {value}
          </Text>

          {/* Label */}
          <Text as="p" variant="bodySm" tone="subdued">
            {label}
          </Text>

          {/* Trend */}
          <Text as="p" variant="bodySm" tone={trendTone}>
            {trendText}
          </Text>

          {/* Sparkline */}
          <SparklineBars colorKey={sparklineColor} />
        </BlockStack>
      </div>
    </div>
  );
}

// ─── Setup Checklist Banner ──────────────────────────────────────────────────

function SetupChecklist({
  quizCount,
  hasProducts,
  hasPublished,
  onFinish,
}: {
  quizCount: number;
  hasProducts: boolean;
  hasPublished: boolean;
  onFinish: () => void;
}) {
  const steps = [
    { label: SETUP_STEPS[0].label, complete: quizCount > 0 },
    { label: SETUP_STEPS[1].label, complete: hasProducts },
    { label: SETUP_STEPS[2].label, complete: hasPublished },
  ];

  const completedCount = steps.filter((s) => s.complete).length;
  const totalCount = steps.length;
  const progressPercent = Math.round((completedCount / totalCount) * 100);

  if (completedCount === totalCount) return null;

  return (
    <Card>
      <BlockStack gap="400">
        <InlineStack align="space-between" blockAlign="center">
          <BlockStack gap="100">
            <Text as="h2" variant="headingMd" fontWeight="bold">
              Complete your setup
            </Text>
            <Text as="p" variant="bodySm" tone="subdued">
              {completedCount} of {totalCount} steps completed
            </Text>
          </BlockStack>
          <Button onClick={onFinish}>Finish setup →</Button>
        </InlineStack>

        <ProgressBar progress={progressPercent} size="small" tone="primary" />

        <BlockStack gap="200">
          {steps.map((step, i) => (
            <InlineStack key={i} gap="300" blockAlign="center">
              <div
                style={{
                  width: 22,
                  height: 22,
                  borderRadius: "50%",
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "center",
                  fontSize: 12,
                  fontWeight: 600,
                  background: step.complete
                    ? "var(--p-color-bg-fill-success)"
                    : "var(--p-color-bg-fill-secondary)",
                  color: step.complete
                    ? "#fff"
                    : "var(--p-color-text-secondary)",
                }}
              >
                {step.complete ? "✓" : i + 1}
              </div>
              <Text
                as="span"
                variant="bodyMd"
                tone={step.complete ? "subdued" : undefined}
              >
                {step.label}
              </Text>
              {!step.complete && i === completedCount && (
                <Badge tone="attention">Next</Badge>
              )}
            </InlineStack>
          ))}
        </BlockStack>
      </BlockStack>
    </Card>
  );
}

// ─── Quiz List Table ─────────────────────────────────────────────────────────

function QuizListTable({
  quizzes,
  onEdit,
  onPreview,
  onCreate,
}: {
  quizzes: QuizRow[];
  onEdit: (id: string) => void;
  onPreview: (id: string) => void;
  onCreate: () => void;
}) {
  const { selectedResources, allResourcesSelected, handleSelectionChange } =
    useIndexResourceState(quizzes);

  if (quizzes.length === 0) {
    return (
      <Card>
        <EmptyState
          heading="Build your first product quiz"
          action={{ content: "Create quiz", onAction: onCreate }}
          image="https://cdn.shopify.com/s/files/1/0262/4071/2726/files/emptystate-files.png"
        >
          <p>
            Guide shoppers to the perfect product with a personalised quiz
            experience.
          </p>
        </EmptyState>
      </Card>
    );
  }

  return (
    <Card padding="0">
      <BlockStack>
        <Box padding="400">
          <InlineStack align="space-between" blockAlign="center">
            <Text as="h2" variant="headingMd">
              Your Quizzes
            </Text>
            <Button size="slim" onClick={onCreate}>
              + New quiz
            </Button>
          </InlineStack>
        </Box>
        <IndexTable
          resourceName={{ singular: "quiz", plural: "quizzes" }}
          itemCount={quizzes.length}
          selectedItemsCount={
            allResourcesSelected ? "All" : selectedResources.length
          }
          onSelectionChange={handleSelectionChange}
          headings={[
            { title: "Quiz" },
            { title: "Status" },
            { title: "Completions", alignment: "end" },
            { title: "Created" },
            { title: "Actions" },
          ]}
        >
          {quizzes.map((quiz, index) => (
            <IndexTable.Row
              id={quiz.id}
              key={quiz.id}
              selected={selectedResources.includes(quiz.id)}
              position={index}
            >
              <IndexTable.Cell>
                <InlineStack gap="300" blockAlign="center">
                  <div
                    style={{
                      width: 36,
                      height: 36,
                      borderRadius: "var(--p-border-radius-200)",
                      background:
                        quiz.status === "active"
                          ? "var(--p-color-bg-fill-success-secondary)"
                          : "var(--p-color-bg-fill-secondary)",
                      display: "flex",
                      alignItems: "center",
                      justifyContent: "center",
                      fontSize: 16,
                    }}
                  >
                    {quiz.status === "active" ? "📊" : "📝"}
                  </div>
                  <BlockStack gap="050">
                    <Button
                      variant="plain"
                      onClick={() => onEdit(quiz.id)}
                    >
                      {quiz.title}
                    </Button>
                  </BlockStack>
                </InlineStack>
              </IndexTable.Cell>
              <IndexTable.Cell>
                <Badge tone={STATUS_TONE[quiz.status]}>
                  {quiz.status === "active"
                    ? "Live"
                    : quiz.status.charAt(0).toUpperCase() +
                      quiz.status.slice(1)}
                </Badge>
              </IndexTable.Cell>
              <IndexTable.Cell>
                <Text as="span" variant="bodyMd" alignment="end">
                  {quiz.completions.toLocaleString()}
                </Text>
              </IndexTable.Cell>
              <IndexTable.Cell>
                <Text as="span" variant="bodySm" tone="subdued">
                  {new Date(quiz.createdAt).toLocaleDateString("en-US", {
                    month: "short",
                    day: "numeric",
                    year: "numeric",
                  })}
                </Text>
              </IndexTable.Cell>
              <IndexTable.Cell>
                <InlineStack gap="200">
                  <Button size="slim" onClick={() => onEdit(quiz.id)}>
                    Edit
                  </Button>
                  <Button
                    size="slim"
                    variant="plain"
                    onClick={() => onPreview(quiz.id)}
                  >
                    Preview
                  </Button>
                </InlineStack>
              </IndexTable.Cell>
            </IndexTable.Row>
          ))}
        </IndexTable>
      </BlockStack>
    </Card>
  );
}

// ─── Main Dashboard Page ─────────────────────────────────────────────────────

export default function Dashboard() {
  const { data } = useLoaderData<typeof loader>();
  const navigate = useNavigate();

  const handleCreateQuiz = useCallback(() => {
    navigate("/app/quizzes/new");
  }, [navigate]);

  const handleViewAnalytics = useCallback(() => {
    navigate("/app/analytics");
  }, [navigate]);

  const handleFinishSetup = useCallback(() => {
    if (data.quizzes.length === 0) {
      navigate("/app/quizzes/new");
    } else {
      navigate(`/app/quizzes/${data.quizzes[0].id}`);
    }
  }, [navigate, data.quizzes]);

  const handleEditQuiz = useCallback(
    (id: string) => navigate(`/app/quizzes/${id}`),
    [navigate],
  );

  const handlePreviewQuiz = useCallback(
    (id: string) => navigate(`/app/quizzes/${id}/preview`),
    [navigate],
  );

  // Compute conversion rate from available data
  const conversionRate =
    data.completions.value > 0
      ? ((data.revenue.value > 0 ? data.completions.value * 0.386 : 0) /
          data.completions.value) *
        100
      : 0;

  const hasPublished = data.quizzes.some(
    (q: QuizRow) => q.status === "active",
  );

  return (
    <Page
      title="Dashboard"
      subtitle="Welcome to QuizSnap"
      primaryAction={{
        content: "+ Create quiz",
        onAction: handleCreateQuiz,
      }}
      secondaryActions={[
        {
          content: "View analytics",
          onAction: handleViewAnalytics,
        },
      ]}
    >
      <BlockStack gap="600">
        {/* ── Statistics Cards Row ─────────────────────────── */}
        <InlineGrid columns={4} gap="400">
          <StatCard
            label="Attributed revenue"
            value={data.revenue.formatted}
            trendText={
              data.revenue.up
                ? `↑ ${data.revenue.trend} vs last month`
                : `↓ ${data.revenue.trend} vs last month`
            }
            trendTone={data.revenue.up ? "success" : "critical"}
            borderColor="#2e7d32"
            sparklineColor="green"
          />
          <StatCard
            label="Quiz completions"
            value={data.completions.formatted}
            trendText={
              data.completions.up
                ? `↑ ${data.completions.trend} vs last month`
                : `↓ ${data.completions.trend} vs last month`
            }
            trendTone={data.completions.up ? "success" : "critical"}
            borderColor="#1565c0"
            sparklineColor="blue"
          />
          <StatCard
            label="Conversion rate"
            value={`${conversionRate.toFixed(1)}%`}
            trendText="↔ Industry avg: 22%"
            trendTone="subdued"
            borderColor="#7b1fa2"
            sparklineColor="violet"
          />
          <StatCard
            label="Emails captured"
            value={data.emailsCaptured.formatted}
            trendText={
              data.emailsCaptured.up
                ? `↑ ${data.emailsCaptured.trend} vs last month`
                : `↓ ${data.emailsCaptured.trend} vs last month`
            }
            trendTone={data.emailsCaptured.up ? "success" : "critical"}
            borderColor="#f57f17"
            sparklineColor="amber"
          />
        </InlineGrid>

        {/* ── Setup Checklist Banner ──────────────────────── */}
        <SetupChecklist
          quizCount={data.quizzes.length}
          hasProducts={false}
          hasPublished={hasPublished}
          onFinish={handleFinishSetup}
        />

        {/* ── Quiz List Table ─────────────────────────────── */}
        <QuizListTable
          quizzes={data.quizzes}
          onEdit={handleEditQuiz}
          onPreview={handlePreviewQuiz}
          onCreate={handleCreateQuiz}
        />
      </BlockStack>
    </Page>
  );
}

// ─── Skeleton loading state ──────────────────────────────────────────────────

export function HydrateFallback() {
  return (
    <SkeletonPage title="Dashboard" primaryAction>
      <BlockStack gap="600">
        <InlineGrid columns={4} gap="400">
          {[0, 1, 2, 3].map((i) => (
            <Card key={i}>
              <BlockStack gap="200">
                <SkeletonDisplayText size="large" />
                <SkeletonBodyText lines={1} />
                <SkeletonBodyText lines={1} />
              </BlockStack>
            </Card>
          ))}
        </InlineGrid>
        <Card>
          <SkeletonBodyText lines={4} />
        </Card>
        <Card>
          <SkeletonBodyText lines={6} />
        </Card>
      </BlockStack>
    </SkeletonPage>
  );
}

export const headers: HeadersFunction = (headersArgs) => {
  return boundary.headers(headersArgs);
};

