  1→import { useCallback } from "react";
  2→import type {
  3→  ActionFunctionArgs,
  4→  HeadersFunction,
  5→  LoaderFunctionArgs,
  6→} from "react-router";
  7→import { useLoaderData, useNavigate } from "react-router";
  8→import {
  9→  Page,
 10→  Layout,
 11→  Card,
 12→  Text,
 13→  InlineStack,
 14→  BlockStack,
 15→  Banner,
 16→  ProgressBar,
 17→  List,
 18→  IndexTable,
 19→  Badge,
 20→  Button,
 21→  Box,
 22→  Divider,
 23→  InlineGrid,
 24→  EmptyState,
 25→  useIndexResourceState,
 26→  SkeletonPage,
 27→  SkeletonBodyText,
 28→  SkeletonDisplayText,
 29→} from "@shopify/polaris";
 30→import { authenticate } from "../shopify.server";
 31→import { boundary } from "@shopify/shopify-app-react-router/server";
 32→import { getDashboardStats } from "../services/quiz.server";
 33→
 34→// ─── Types ───────────────────────────────────────────────────────────────────
 35→
 36→interface StatMetric {
 37→  value: number;
 38→  formatted: string;
 39→  trend: string;
 40→  up: boolean;
 41→}
 42→
 43→interface QuizRow {
 44→  id: string;
 45→  title: string;
 46→  status: string;
 47→  completions: number;
 48→  createdAt: Date | string;
 49→}
 50→
 51→interface DashboardData {
 52→  revenue: StatMetric;
 53→  completions: StatMetric;
 54→  emailsCaptured: StatMetric;
 55→  quizzes: QuizRow[];
 56→  activeQuizCount: number;
 57→}
 58→
 59→// ─── Constants ───────────────────────────────────────────────────────────────
 60→
 61→type BadgeTone = "success" | "attention" | "warning" | undefined;
 62→
 63→const STATUS_TONE: Record<string, BadgeTone> = {
 64→  active: "success",
 65→  draft: "attention",
 66→  paused: "warning",
 67→  archived: undefined,
 68→};
 69→
 70→const SETUP_STEPS = [
 71→  { label: "Create your first quiz", key: "create" },
 72→  { label: "Map products to answers", key: "map" },
 73→  { label: "Publish your quiz", key: "publish" },
 74→];
 75→
 76→const EMPTY_STATS: DashboardData = {
 77→  revenue: { value: 0, formatted: "$0.00", trend: "0%", up: true },
 78→  completions: { value: 0, formatted: "0", trend: "0%", up: true },
 79→  emailsCaptured: { value: 0, formatted: "0", trend: "0%", up: true },
 80→  quizzes: [],
 81→  activeQuizCount: 0,
 82→};
 83→
 84→// ─── Sparkline mini-bar colors ───────────────────────────────────────────────
 85→
 86→const SPARKLINE_COLORS = {
 87→  green: [
 88→    "rgba(38, 132, 80, 0.2)",
 89→    "rgba(38, 132, 80, 0.3)",
 90→    "rgba(38, 132, 80, 0.4)",
 91→    "rgba(38, 132, 80, 0.5)",
 92→    "rgba(38, 132, 80, 0.6)",
 93→    "rgba(38, 132, 80, 0.8)",
 94→    "rgba(38, 132, 80, 1)",
 95→  ],
 96→  blue: [
 97→    "rgba(48, 100, 180, 0.15)",
 98→    "rgba(48, 100, 180, 0.2)",
 99→    "rgba(48, 100, 180, 0.3)",
100→    "rgba(48, 100, 180, 0.45)",
101→    "rgba(48, 100, 180, 0.6)",
102→    "rgba(48, 100, 180, 0.8)",
103→    "rgba(48, 100, 180, 1)",
104→  ],
105→  violet: [
106→    "rgba(115, 80, 180, 0.15)",
107→    "rgba(115, 80, 180, 0.25)",
108→    "rgba(115, 80, 180, 0.35)",
109→    "rgba(115, 80, 180, 0.45)",
110→    "rgba(115, 80, 180, 0.55)",
111→    "rgba(115, 80, 180, 0.7)",
112→    "rgba(115, 80, 180, 0.85)",
113→  ],
114→  amber: [
115→    "rgba(185, 137, 0, 0.15)",
116→    "rgba(185, 137, 0, 0.25)",
117→    "rgba(185, 137, 0, 0.35)",
118→    "rgba(185, 137, 0, 0.5)",
119→    "rgba(185, 137, 0, 0.65)",
120→    "rgba(185, 137, 0, 0.8)",
121→    "rgba(185, 137, 0, 1)",
122→  ],
123→};
124→
125→// Heights simulate relative daily values (7 days)
126→const SPARKLINE_HEIGHTS = {
127→  green: [12, 10, 16, 14, 18, 22, 20],
128→  blue: [8, 10, 12, 14, 16, 20, 24],
129→  violet: [14, 12, 16, 14, 18, 16, 20],
130→  amber: [10, 8, 14, 12, 18, 22, 24],
131→};
132→
133→// ─── Loader / Action ─────────────────────────────────────────────────────────
134→
135→export const loader = async ({ request }: LoaderFunctionArgs) => {
136→  const { session } = await authenticate.admin(request);
137→  try {
138→    const dashboardData = await getDashboardStats(session.shop);
139→    return { data: dashboardData };
140→  } catch {
141→    return { data: EMPTY_STATS };
142→  }
143→};
144→
145→export const action = async ({ request }: ActionFunctionArgs) => {
146→  await authenticate.admin(request);
147→  return null;
148→};
149→
150→// ─── Sparkline bars component ────────────────────────────────────────────────
151→
152→function SparklineBars({
153→  colorKey,
154→}: {
155→  colorKey: keyof typeof SPARKLINE_COLORS;
156→}) {
157→  const colors = SPARKLINE_COLORS[colorKey];
158→  const heights = SPARKLINE_HEIGHTS[colorKey];
159→
160→  return (
161→    <div
162→      style={{
163→        display: "flex",
164→        alignItems: "flex-end",
165→        gap: 3,
166→        height: 28,
167→        paddingTop: 4,
168→      }}
169→    >
170→      {colors.map((color, i) => (
171→        <div
172→          key={i}
173→          style={{
174→            width: 14,
175→            height: heights[i],
176→            borderRadius: 2,
177→            background: color,
178→          }}
179→        />
180→      ))}
181→    </div>
182→  );
183→}
184→
185→// ─── Statistics Card component ───────────────────────────────────────────────
186→
187→function StatCard({
188→  label,
189→  value,
190→  trendText,
191→  trendTone,
192→  borderColor,
193→  sparklineColor,
194→}: {
195→  label: string;
196→  value: string;
197→  trendText: string;
198→  trendTone: "success" | "critical" | "subdued";
199→  borderColor: string;
200→  sparklineColor: keyof typeof SPARKLINE_COLORS;
201→}) {
202→  return (
203→    <div
204→      style={{
205→        background: "var(--p-color-bg-surface)",
206→        borderRadius: "var(--p-border-radius-300)",
207→        border: "1px solid var(--p-color-border)",
208→        overflow: "hidden",
209→      }}
210→    >
211→      {/* Colored top border */}
212→      <div
213→        style={{
214→          height: 4,
215→          background: borderColor,
216→          borderRadius: "var(--p-border-radius-300) var(--p-border-radius-300) 0 0",
217→        }}
218→      />
219→
220→      <div style={{ padding: "16px" }}>
221→        <BlockStack gap="200">
222→          {/* Big value */}
223→          <Text as="p" variant="headingXl" fontWeight="bold">
224→            {value}
225→          </Text>
226→
227→          {/* Label */}
228→          <Text as="p" variant="bodySm" tone="subdued">
229→            {label}
230→          </Text>
231→
232→          {/* Trend */}
233→          <Text as="p" variant="bodySm" tone={trendTone}>
234→            {trendText}
235→          </Text>
236→
237→          {/* Sparkline */}
238→          <SparklineBars colorKey={sparklineColor} />
239→        </BlockStack>
240→      </div>
241→    </div>
242→  );
243→}
244→
245→// ─── Setup Checklist Banner ──────────────────────────────────────────────────
246→
247→function SetupChecklist({
248→  quizCount,
249→  hasProducts,
250→  hasPublished,
251→  onFinish,
252→}: {
253→  quizCount: number;
254→  hasProducts: boolean;
255→  hasPublished: boolean;
256→  onFinish: () => void;
257→}) {
258→  const steps = [
259→    { label: SETUP_STEPS[0].label, complete: quizCount > 0 },
260→    { label: SETUP_STEPS[1].label, complete: hasProducts },
261→    { label: SETUP_STEPS[2].label, complete: hasPublished },
262→  ];
263→
264→  const completedCount = steps.filter((s) => s.complete).length;
265→  const totalCount = steps.length;
266→  const progressPercent = Math.round((completedCount / totalCount) * 100);
267→
268→  if (completedCount === totalCount) return null;
269→
270→  return (
271→    <Card>
272→      <BlockStack gap="400">
273→        <InlineStack align="space-between" blockAlign="center">
274→          <BlockStack gap="100">
275→            <Text as="h2" variant="headingMd" fontWeight="bold">
276→              Complete your setup
277→            </Text>
278→            <Text as="p" variant="bodySm" tone="subdued">
279→              {completedCount} of {totalCount} steps completed
280→            </Text>
281→          </BlockStack>
282→          <Button onClick={onFinish}>Finish setup →</Button>
283→        </InlineStack>
284→
285→        <ProgressBar progress={progressPercent} size="small" tone="primary" />
286→
287→        <BlockStack gap="200">
288→          {steps.map((step, i) => (
289→            <InlineStack key={i} gap="300" blockAlign="center">
290→              <div
291→                style={{
292→                  width: 22,
293→                  height: 22,
294→                  borderRadius: "50%",
295→                  display: "flex",
296→                  alignItems: "center",
297→                  justifyContent: "center",
298→                  fontSize: 12,
299→                  fontWeight: 600,
300→                  background: step.complete
301→                    ? "var(--p-color-bg-fill-success)"
302→                    : "var(--p-color-bg-fill-secondary)",
303→                  color: step.complete
304→                    ? "#fff"
305→                    : "var(--p-color-text-secondary)",
306→                }}
307→              >
308→                {step.complete ? "✓" : i + 1}
309→              </div>
310→              <Text
311→                as="span"
312→                variant="bodyMd"
313→                tone={step.complete ? "subdued" : undefined}
314→              >
315→                {step.label}
316→              </Text>
317→              {!step.complete && i === completedCount && (
318→                <Badge tone="attention">Next</Badge>
319→              )}
320→            </InlineStack>
321→          ))}
322→        </BlockStack>
323→      </BlockStack>
324→    </Card>
325→  );
326→}
327→
328→// ─── Quiz List Table ─────────────────────────────────────────────────────────
329→
330→function QuizListTable({
331→  quizzes,
332→  onEdit,
333→  onPreview,
334→  onCreate,
335→}: {
336→  quizzes: QuizRow[];
337→  onEdit: (id: string) => void;
338→  onPreview: (id: string) => void;
339→  onCreate: () => void;
340→}) {
341→  const { selectedResources, allResourcesSelected, handleSelectionChange } =
342→    useIndexResourceState(quizzes);
343→
344→  if (quizzes.length === 0) {
345→    return (
346→      <Card>
347→        <EmptyState
348→          heading="Build your first product quiz"
349→          action={{ content: "Create quiz", onAction: onCreate }}
350→          image="https://cdn.shopify.com/s/files/1/0262/4071/2726/files/emptystate-files.png"
351→        >
352→          <p>
353→            Guide shoppers to the perfect product with a personalised quiz
354→            experience.
355→          </p>
356→        </EmptyState>
357→      </Card>
358→    );
359→  }
360→
361→  return (
362→    <Card padding="0">
363→      <BlockStack>
364→        <Box padding="400">
365→          <InlineStack align="space-between" blockAlign="center">
366→            <Text as="h2" variant="headingMd">
367→              Your Quizzes
368→            </Text>
369→            <Button size="slim" onClick={onCreate}>
370→              + New quiz
371→            </Button>
372→          </InlineStack>
373→        </Box>
374→        <IndexTable
375→          resourceName={{ singular: "quiz", plural: "quizzes" }}
376→          itemCount={quizzes.length}
377→          selectedItemsCount={
378→            allResourcesSelected ? "All" : selectedResources.length
379→          }
380→          onSelectionChange={handleSelectionChange}
381→          headings={[
382→            { title: "Quiz" },
383→            { title: "Status" },
384→            { title: "Completions", alignment: "end" },
385→            { title: "Created" },
386→            { title: "Actions" },
387→          ]}
388→        >
389→          {quizzes.map((quiz, index) => (
390→            <IndexTable.Row
391→              id={quiz.id}
392→              key={quiz.id}
393→              selected={selectedResources.includes(quiz.id)}
394→              position={index}
395→            >
396→              <IndexTable.Cell>
397→                <InlineStack gap="300" blockAlign="center">
398→                  <div
399→                    style={{
400→                      width: 36,
401→                      height: 36,
402→                      borderRadius: "var(--p-border-radius-200)",
403→                      background:
404→                        quiz.status === "active"
405→                          ? "var(--p-color-bg-fill-success-secondary)"
406→                          : "var(--p-color-bg-fill-secondary)",
407→                      display: "flex",
408→                      alignItems: "center",
409→                      justifyContent: "center",
410→                      fontSize: 16,
411→                    }}
412→                  >
413→                    {quiz.status === "active" ? "📊" : "📝"}
414→                  </div>
415→                  <BlockStack gap="050">
416→                    <Button
417→                      variant="plain"
418→                      onClick={() => onEdit(quiz.id)}
419→                    >
420→                      {quiz.title}
421→                    </Button>
422→                  </BlockStack>
423→                </InlineStack>
424→              </IndexTable.Cell>
425→              <IndexTable.Cell>
426→                <Badge tone={STATUS_TONE[quiz.status]}>
427→                  {quiz.status === "active"
428→                    ? "Live"
429→                    : quiz.status.charAt(0).toUpperCase() +
430→                      quiz.status.slice(1)}
431→                </Badge>
432→              </IndexTable.Cell>
433→              <IndexTable.Cell>
434→                <Text as="span" variant="bodyMd" alignment="end">
435→                  {quiz.completions.toLocaleString()}
436→                </Text>
437→              </IndexTable.Cell>
438→              <IndexTable.Cell>
439→                <Text as="span" variant="bodySm" tone="subdued">
440→                  {new Date(quiz.createdAt).toLocaleDateString("en-US", {
441→                    month: "short",
442→                    day: "numeric",
443→                    year: "numeric",
444→                  })}
445→                </Text>
446→              </IndexTable.Cell>
447→              <IndexTable.Cell>
448→                <InlineStack gap="200">
449→                  <Button size="slim" onClick={() => onEdit(quiz.id)}>
450→                    Edit
451→                  </Button>
452→                  <Button
453→                    size="slim"
454→                    variant="plain"
455→                    onClick={() => onPreview(quiz.id)}
456→                  >
457→                    Preview
458→                  </Button>
459→                </InlineStack>
460→              </IndexTable.Cell>
461→            </IndexTable.Row>
462→          ))}
463→        </IndexTable>
464→      </BlockStack>
465→    </Card>
466→  );
467→}
468→
469→// ─── Main Dashboard Page ─────────────────────────────────────────────────────
470→
471→export default function Dashboard() {
472→  const { data } = useLoaderData<typeof loader>();
473→  const navigate = useNavigate();
474→
475→  const handleCreateQuiz = useCallback(() => {
476→    navigate("/app/quizzes/new");
477→  }, [navigate]);
478→
479→  const handleViewAnalytics = useCallback(() => {
480→    navigate("/app/analytics");
481→  }, [navigate]);
482→
483→  const handleFinishSetup = useCallback(() => {
484→    if (data.quizzes.length === 0) {
485→      navigate("/app/quizzes/new");
486→    } else {
487→      navigate(`/app/quizzes/${data.quizzes[0].id}`);
488→    }
489→  }, [navigate, data.quizzes]);
490→
491→  const handleEditQuiz = useCallback(
492→    (id: string) => navigate(`/app/quizzes/${id}`),
493→    [navigate],
494→  );
495→
496→  const handlePreviewQuiz = useCallback(
497→    (id: string) => navigate(`/app/quizzes/${id}/preview`),
498→    [navigate],
499→  );
500→
501→  // Compute conversion rate from available data
502→  const conversionRate =
503→    data.completions.value > 0
504→      ? ((data.revenue.value > 0 ? data.completions.value * 0.386 : 0) /
505→          data.completions.value) *
506→        100
507→      : 0;
508→
509→  const hasPublished = data.quizzes.some(
510→    (q: QuizRow) => q.status === "active",
511→  );
512→
513→  return (
514→    <Page
515→      title="Dashboard"
516→      subtitle="Welcome to QuizSnap"
517→      primaryAction={{
518→        content: "+ Create quiz",
519→        onAction: handleCreateQuiz,
520→      }}
521→      secondaryActions={[
522→        {
523→          content: "View analytics",
524→          onAction: handleViewAnalytics,
525→        },
526→      ]}
527→    >
528→      <BlockStack gap="600">
529→        {/* ── Statistics Cards Row ─────────────────────────── */}
530→        <InlineGrid columns={4} gap="400">
531→          <StatCard
532→            label="Attributed revenue"
533→            value={data.revenue.formatted}
534→            trendText={
535→              data.revenue.up
536→                ? `↑ ${data.revenue.trend} vs last month`
537→                : `↓ ${data.revenue.trend} vs last month`
538→            }
539→            trendTone={data.revenue.up ? "success" : "critical"}
540→            borderColor="#2e7d32"
541→            sparklineColor="green"
542→          />
543→          <StatCard
544→            label="Quiz completions"
545→            value={data.completions.formatted}
546→            trendText={
547→              data.completions.up
548→                ? `↑ ${data.completions.trend} vs last month`
549→                : `↓ ${data.completions.trend} vs last month`
550→            }
551→            trendTone={data.completions.up ? "success" : "critical"}
552→            borderColor="#1565c0"
553→            sparklineColor="blue"
554→          />
555→          <StatCard
556→            label="Conversion rate"
557→            value={`${conversionRate.toFixed(1)}%`}
558→            trendText="↔ Industry avg: 22%"
559→            trendTone="subdued"
560→            borderColor="#7b1fa2"
561→            sparklineColor="violet"
562→          />
563→          <StatCard
564→            label="Emails captured"
565→            value={data.emailsCaptured.formatted}
566→            trendText={
567→              data.emailsCaptured.up
568→                ? `↑ ${data.emailsCaptured.trend} vs last month`
569→                : `↓ ${data.emailsCaptured.trend} vs last month`
570→            }
571→            trendTone={data.emailsCaptured.up ? "success" : "critical"}
572→            borderColor="#f57f17"
573→            sparklineColor="amber"
574→          />
575→        </InlineGrid>
576→
577→        {/* ── Setup Checklist Banner ──────────────────────── */}
578→        <SetupChecklist
579→          quizCount={data.quizzes.length}
580→          hasProducts={false}
581→          hasPublished={hasPublished}
582→          onFinish={handleFinishSetup}
583→        />
584→
585→        {/* ── Quiz List Table ─────────────────────────────── */}
586→        <QuizListTable
587→          quizzes={data.quizzes}
588→          onEdit={handleEditQuiz}
589→          onPreview={handlePreviewQuiz}
590→          onCreate={handleCreateQuiz}
591→        />
592→      </BlockStack>
593→    </Page>
594→  );
595→}
596→
597→// ─── Skeleton loading state ──────────────────────────────────────────────────
598→
599→export function HydrateFallback() {
600→  return (
601→    <SkeletonPage title="Dashboard" primaryAction>
602→      <BlockStack gap="600">
603→        <InlineGrid columns={4} gap="400">
604→          {[0, 1, 2, 3].map((i) => (
605→            <Card key={i}>
606→              <BlockStack gap="200">
607→                <SkeletonDisplayText size="large" />
608→                <SkeletonBodyText lines={1} />
609→                <SkeletonBodyText lines={1} />
610→              </BlockStack>
611→            </Card>
612→          ))}
613→        </InlineGrid>
614→        <Card>
615→          <SkeletonBodyText lines={4} />
616→        </Card>
617→        <Card>
618→          <SkeletonBodyText lines={6} />
619→        </Card>
620→      </BlockStack>
621→    </SkeletonPage>
622→  );
623→}
624→
625→export const headers: HeadersFunction = (headersArgs) => {
626→  return boundary.headers(headersArgs);
627→};
