 719→      showToast(String(actionData.error), {
 720→        duration: 4000,
 721→        isError: true,
 722→      });
 723→    }
 724→  }, [actionData]);
 725→
 726→  const tabs = [
 727→    { id: "questions", content: "Questions", panelID: "questions-panel" },
 728→    { id: "mapping", content: "Product Mapping", panelID: "mapping-panel" },
 729→    { id: "design", content: "Design", panelID: "design-panel" },
 730→  ];
 731→
 732→  const handleTabChange = useCallback((index: number) => {
 733→    setSelectedTab(index);
 734→  }, []);
 735→
 736→  // Save questions tab
 737→  const handleSaveQuestions = useCallback(() => {
 738→    const formData = new FormData();
 739→    formData.set("intent", "save-questions");
 740→    formData.set(
 741→      "questions",
 742→      JSON.stringify(
 743→        questions.map((q, qi) => ({
 744→          id: q.id,
 745→          title: q.title,
 746→          type: q.type,
 747→          required: q.required,
 748→          position: qi,
 749→          options: q.options.map((o, oi) => ({
 750→            id: o.id,
 751→            label: o.label,
 752→            score: o.score,
 753→            productTags: o.productTags,
 754→            position: oi,
 755→          })),
 756→        })),
 757→      ),
 758→    );
 759→    submit(formData, { method: "POST" });
 760→  }, [questions, submit]);
 761→
 762→  // Save design tab
 763→  const handleSaveDesign = useCallback(() => {
 764→    const stylingObj = {
 765→      buttonColor: design.buttonColor,
 766→      buttonText: design.buttonText,
 767→      resultsHeading: design.resultsHeading,
 768→      showProgressBar: design.showProgressBar,
 769→    };
 770→    const formData = new FormData();
 771→    formData.set("intent", "save-design");
 772→    formData.set("title", design.quizTitle);
 773→    formData.set("description", design.description);
 774→    formData.set("styling", JSON.stringify(stylingObj));
 775→    submit(formData, { method: "POST" });
 776→  }, [design, submit]);
 777→
 778→  const handlePublish = useCallback(() => {
 779→    const formData = new FormData();
 780→    formData.set("intent", "publish");
 781→    submit(formData, { method: "POST" });
 782→  }, [submit]);
 783→
 784→  const handleUnpublish = useCallback(() => {
 785→    const formData = new FormData();
 786→    formData.set("intent", "unpublish");
 787→    submit(formData, { method: "POST" });
 788→  }, [submit]);
 789→
 790→  const handleDeleteConfirm = useCallback(() => {
 791→    const formData = new FormData();
 792→    formData.set("intent", "delete");
 793→    submit(formData, { method: "POST" });
 794→  }, [submit]);
 795→
 796→  const handlePreview = useCallback(() => {
 797→    navigate(`/app/quizzes/${quizId}/preview`);
 798→  }, [navigate, quizId]);
 799→
 800→  const handleBack = useCallback(() => {
 801→    navigate("/app/quizzes");
 802→  }, [navigate]);
 803→
 804→  // --- Question handlers ---
 805→
 806→  const handleSelectQuestion = useCallback((index: number) => {
 807→    setSelectedQuestionIndex(index);
 808→  }, []);
 809→
 810→  const handleUpdateQuestion = useCallback(
 811→    (field: string, value: string | boolean) => {
 812→      setQuestions((prev) => {
 813→        const updated = [...prev];
 814→        updated[selectedQuestionIndex] = {
 815→          ...updated[selectedQuestionIndex],
 816→          [field]: value,
 817→        };
 818→        return updated;
 819→      });
 820→    },
 821→    [selectedQuestionIndex],
 822→  );
 823→
 824→  const handleAddQuestion = useCallback(() => {
 825→    const newId = `new-${Date.now()}`;
 826→    const newQuestion: Question = {
 827→      id: newId,
 828→      title: "",
 829→      type: "single",
