 831→      position: questions.length,
 832→      options: [
 833→        { id: `${newId}a1`, label: "Option 1", score: 0, productTags: [], position: 0 },
 834→        { id: `${newId}a2`, label: "Option 2", score: 0, productTags: [], position: 1 },
 835→      ],
