 838→    setSelectedQuestionIndex(questions.length);
 839→  }, [questions.length]);
 840→
 841→  const handleAddOption = useCallback(() => {
 842→    setQuestions((prev) => {
 843→      const updated = [...prev];
 844→      const question = { ...updated[selectedQuestionIndex] };
 845→      const newOptionId = `${question.id}a${Date.now()}`;
 846→      question.options = [
 847→        ...question.options,
 848→        {
 849→          id: newOptionId,
 850→          label: "",
 851→          score: 0,
 852→          productTags: [],
 853→          position: question.options.length,
 854→        },
 855→      ];
 856→      updated[selectedQuestionIndex] = question;
