 858→    });
 859→  }, [selectedQuestionIndex]);
 860→
 861→  const handleUpdateOption = useCallback(
 862→    (optionId: string, value: string) => {
 863→      setQuestions((prev) => {
 864→        const updated = [...prev];
 865→        const question = { ...updated[selectedQuestionIndex] };
