 870→        return updated;
 871→      });
 872→    },
 873→    [selectedQuestionIndex],
 874→  );
 875→
 876→  const handleDeleteOption = useCallback(
 877→    (optionId: string) => {
 878→      setQuestions((prev) => {
 879→        const updated = [...prev];
