 886→      });
 887→    },
 888→    [selectedQuestionIndex],
 889→  );
 890→
 891→  // --- Product mapping handlers ---
 892→
 893→  const handleAddProduct = useCallback(
 894→    (questionId: string, optionId: string, tag: string) => {
 895→      setQuestions((prev) =>
 896→        prev.map((q) =>
