 903→                        ...opt,
 904→                        productTags: [...opt.productTags, tag],
 905→                      }
 906→                    : opt,
 907→                ),
 908→              }
 909→            : q,
 910→        ),
 911→      );
 912→    },
 913→    [],
 914→  );
 915→
 916→  const handleRemoveProduct = useCallback(
 917→    (questionId: string, optionId: string, tag: string) => {
 918→      setQuestions((prev) =>
 919→        prev.map((q) =>
 920→          q.id === questionId
 921→            ? {
 922→                ...q,
 923→                options: q.options.map((opt) =>
 924→                  opt.id === optionId
 925→                    ? {
 926→                        ...opt,
 927→                        productTags: opt.productTags.filter((t) => t !== tag),
 928→                      }
 929→                    : opt,
 930→                ),
 931→              }
 932→            : q,
 933→        ),
 934→      );
 935→    },
 936→    [],
 937→  );
 938→
 939→  // --- Design handlers ---
 940→
 941→  const handleUpdateDesign = useCallback(
 942→    (field: keyof DesignSettings, value: string | boolean) => {
 943→      setDesign((prev) => ({ ...prev, [field]: value }));
 944→    },
 945→    [],
 946→  );
 947→
 948→  // Current save action depends on active tab
 949→  const handleSave = useCallback(() => {
 950→    if (selectedTab === 2) {
 951→      handleSaveDesign();
 952→    } else {
 953→      handleSaveQuestions();
 954→    }
 955→  }, [selectedTab, handleSaveDesign, handleSaveQuestions]);
 956→
 957→  const isLive = quiz.status === "active";
 958→  const statusTone = isLive
 959→    ? "success"
 960→    : quiz.status === "draft"
 961→      ? "attention"
 962→      : undefined;
 963→  const statusLabel = isLive ? "Live" : "Draft";
 964→
 965→  return (
 966→    <>
 967→      <Page
