 973→          onAction: handleSave,
 974→        }}
 975→        secondaryActions={[
 976→          {
 977→            content: "Preview",
 978→            onAction: handlePreview,
 979→          },
 980→          isLive
 981→            ? {
 982→                content: "Unpublish",
 983→                onAction: handleUnpublish,
 984→              }
 985→            : {
 986→                content: "Publish",
 987→                onAction: handlePublish,
 988→              },
 989→          {
 990→            content: "Delete",
 991→            destructive: true,
 992→            onAction: () => setDeleteModalOpen(true),
 993→          },
 994→        ]}
 995→      >
 996→        <BlockStack gap="400">
 997→          <Card padding="0">
 998→            <Tabs tabs={tabs} selected={selectedTab} onSelect={handleTabChange}>
 999→              <Box padding="400">
1000→                {selectedTab === 0 && (
1001→                  <QuestionsTab
1002→                    questions={questions}
1003→                    selectedQuestionIndex={selectedQuestionIndex}
1004→                    onSelectQuestion={handleSelectQuestion}
1005→                    onUpdateQuestion={handleUpdateQuestion}
1006→                    onAddQuestion={handleAddQuestion}
1007→                    onAddOption={handleAddOption}
1008→                    onUpdateOption={handleUpdateOption}
1009→                    onDeleteOption={handleDeleteOption}
1010→                  />
1011→                )}
1012→                {selectedTab === 1 && (
1013→                  <ProductMappingTab
1014→                    questions={questions}
1015→                    onAddProduct={handleAddProduct}
1016→                    onRemoveProduct={handleRemoveProduct}
1017→                  />
