import { showToast } from "~/utils/toast";
import { useState, useCallback, useEffect } from "react";
import {
  data,
  redirect,
  type ActionFunctionArgs,
  type HeadersFunction,
  type LoaderFunctionArgs,
} from "react-router";
import { useLoaderData, useActionData, useNavigate, useSubmit } from "react-router";
import {
  Page,
  Layout,
  Card,
  Text,
  InlineStack,
  BlockStack,
  Badge,
  Button,
  Box,
  Divider,
  TextField,
  Select,
  Tabs,
  Tag,
  Checkbox,
  FormLayout,
  Banner,
  EmptyState,
  Modal,
  SkeletonPage,
  SkeletonBodyText,
} from "@shopify/polaris";
import {
  PlusIcon,
  DeleteIcon,
  DragHandleIcon,
  EditIcon,
  EyeFirstIcon,
  SaveIcon,
  XIcon,
  ProductIcon,
} from "@shopify/polaris-icons";
import { authenticate } from "../shopify.server";
import { boundary } from "@shopify/shopify-app-react-router/server";
import db from "../db.server";

// --- Types ---

interface AnswerOption {
  id: string;
  label: string;
  score: number;
  productTags: string[];
  position: number;
}

interface Question {
  id: string;
  title: string;
  type: string;
  required: boolean;
  position: number;
  options: AnswerOption[];
}

interface DesignSettings {
  quizTitle: string;
  description: string;
  buttonColor: string;
  buttonText: string;
  resultsHeading: string;
  showProgressBar: boolean;
}

interface LoaderData {
  quiz: {
    id: string;
    title: string;
    description: string | null;
    slug: string;
    status: string;
    settings: string;
    styling: string;
  };
  questions: Question[];
  designSettings: DesignSettings;
}

// --- Helpers ---

const questionTypeOptions = [
  { label: "Single choice", value: "single" },
  { label: "Multiple choice", value: "multiple" },
  { label: "Image choice", value: "image-choice" },
  { label: "Dropdown", value: "dropdown" },
  { label: "Slider", value: "slider" },
  { label: "Email capture", value: "email" },
  { label: "Text input", value: "text-input" },
  { label: "Rating", value: "rating" },
];

const questionTypeLabel = (type: string): string =>
  questionTypeOptions.find((o) => o.value === type)?.label ?? type;

function parseSafe<T>(str: string, fallback: T): T {
  try {
    return JSON.parse(str) as T;
  } catch {
    return fallback;
  }
}

// --- Loader ---

export const loader = async ({ request, params }: LoaderFunctionArgs) => {
  const { session } = await authenticate.admin(request);
  const quizId = params.id;

  if (!quizId) {
    throw data({ error: "Missing quiz ID" }, { status: 400 });
  }

  try {
    const quiz = await db.quiz.findFirst({
      where: { id: quizId, shop: session.shop },
      include: {
        questions: {
          include: { answers: { orderBy: { position: "asc" } } },
          orderBy: { position: "asc" },
        },
      },
    });

    if (!quiz) {
      throw data({ error: "Quiz not found" }, { status: 404 });
    }

    const stylingObj = parseSafe<{
      buttonColor?: string;
      buttonText?: string;
      resultsHeading?: string;
      showProgressBar?: boolean;
    }>(quiz.styling, {});

    const designSettings: DesignSettings = {
      quizTitle: quiz.title,
      description: quiz.description ?? "",
      buttonColor: stylingObj.buttonColor ?? "#5C6AC4",
      buttonText: stylingObj.buttonText ?? "Next",
      resultsHeading: stylingObj.resultsHeading ?? "Your Results",
      showProgressBar: stylingObj.showProgressBar ?? true,
    };

    const questions: Question[] = quiz.questions.map((q) => ({
      id: q.id,
      title: q.title,
      type: q.type,
      required: q.required,
      position: q.position,
      options: q.answers.map((a) => ({
        id: a.id,
        label: a.text,
        score: a.score,
        productTags: parseSafe(a.productTags, [] as string[]),
        position: a.position,
      })),
    }));

    return {
      quiz: {
        id: quiz.id,
        title: quiz.title,
        description: quiz.description,
        slug: quiz.slug,
        status: quiz.status,
        settings: quiz.settings,
        styling: quiz.styling,
      },
      questions,
      designSettings,
    } as LoaderData;
  } catch (error) {
    if (error instanceof Response) throw error;
    throw data({ error: "Failed to load quiz" }, { status: 500 });
  }
};

// --- Action ---

export const action = async ({ request, params }: ActionFunctionArgs) => {
  const { session } = await authenticate.admin(request);
  const quizId = params.id!;
  const formData = await request.formData();
  const intent = String(formData.get("intent") ?? "");

  try {
    // Verify ownership before any mutation
    const quiz = await db.quiz.findFirst({
      where: { id: quizId, shop: session.shop },
    });
    if (!quiz) {
      return data({ error: "Quiz not found" }, { status: 404 });
    }

    switch (intent) {
      case "save-design": {
        const title = String(formData.get("title") ?? "").trim();
        const description =
          String(formData.get("description") ?? "").trim() || null;
        const styling = String(formData.get("styling") ?? "{}");
        if (!title) {
          return data({ error: "Title is required" }, { status: 400 });
        }
        await db.quiz.update({
          where: { id: quizId },
          data: { title, description, styling, updatedAt: new Date() },
        });
        return { success: true, message: "Design saved!" };
      }

      case "publish": {
        await db.quiz.update({
          where: { id: quizId },
          data: {
            status: "active",
            publishedAt: quiz.publishedAt ?? new Date(),
          },
        });
        return {
          success: true,
          message: "Quiz published! It's now live on your storefront.",
        };
      }

      case "unpublish": {
        await db.quiz.update({
          where: { id: quizId },
          data: { status: "draft" },
        });
        return { success: true, message: "Quiz unpublished." };
      }

      case "delete": {
        await db.quiz.delete({ where: { id: quizId } });
        return redirect("/app/quizzes");
      }

      case "save-questions": {
        const questionsJson = String(formData.get("questions") ?? "[]");
        let questions: Array<{
          id?: string;
          title: string;
          type: string;
          required: boolean;
          position: number;
          options: Array<{
            id?: string;
            label: string;
            score: number;
            productTags: string[];
            position: number;
          }>;
        }>;

        try {
          questions = JSON.parse(questionsJson);
        } catch {
          return data({ error: "Invalid questions data" }, { status: 400 });
        }

        // Delete all existing questions (cascade deletes answers)
        await db.question.deleteMany({ where: { quizId } });

        // Re-create all questions with their answers
        for (const q of questions) {
          await db.question.create({
            data: {
              quizId,
              title: q.title,
              type: q.type,
              required: q.required,
              position: q.position,
              answers: {
                create: q.options.map((a) => ({
                  text: a.label,
                  score: a.score,
                  productTags: JSON.stringify(a.productTags),
                  position: a.position,
                })),
              },
            },
          });
        }
        return { success: true, message: "Questions saved!" };
      }

      default:
        return data({ error: "Unknown action" }, { status: 400 });
    }
  } catch (error) {
    if (error instanceof Response) throw error;
    console.error(`Quiz action "${intent}" failed:`, error);
    return data(
      { error: "Action failed. Please try again." },
      { status: 500 },
    );
  }
};

// --- HydrateFallback (skeleton shown during navigation) ---

export function HydrateFallback() {
  return (
    <SkeletonPage primaryAction backAction>
      <Layout>
        <Layout.Section>
          <Card>
            <SkeletonBodyText lines={8} />
          </Card>
        </Layout.Section>
        <Layout.Section variant="oneThird">
          <Card>
            <SkeletonBodyText lines={5} />
          </Card>
        </Layout.Section>
      </Layout>
    </SkeletonPage>
  );
}

// --- Tab: Questions ---

function QuestionsTab({
  questions,
  selectedQuestionIndex,
  onSelectQuestion,
  onUpdateQuestion,
  onAddQuestion,
  onAddOption,
  onUpdateOption,
  onDeleteOption,
  onDeleteQuestion,
}: {
  questions: Question[];
  selectedQuestionIndex: number;
  onSelectQuestion: (index: number) => void;
  onUpdateQuestion: (field: string, value: string | boolean) => void;
  onAddQuestion: () => void;
  onAddOption: () => void;
  onUpdateOption: (optionId: string, value: string) => void;
  onDeleteOption: (optionId: string) => void;
  onDeleteQuestion: (index: number) => void;
}) {
  const selectedQuestion = questions[selectedQuestionIndex];

  return (
    <Layout>
      {/* Left sidebar — question list */}
      <Layout.Section variant="oneThird">
        <BlockStack gap="300">
          <InlineStack align="space-between" blockAlign="center">
            <Text as="h3" variant="headingSm" fontWeight="semibold">
              Questions
            </Text>
            <Badge tone="info">{String(questions.length)}</Badge>
          </InlineStack>

          {questions.length === 0 ? (
            <Box
              background="bg-surface-secondary"
              borderRadius="200"
              padding="400"
            >
              <BlockStack gap="200" align="center">
                <Text as="p" variant="bodySm" tone="subdued" alignment="center">
                  No questions yet. Add your first question to get started.
                </Text>
              </BlockStack>
            </Box>
          ) : (
            <BlockStack gap="100">
              {questions.map((q, index) => {
                const isSelected = index === selectedQuestionIndex;
                return (
                  <Box
                    key={q.id}
                    background={
                      isSelected ? "bg-surface-selected" : "bg-surface"
                    }
                    borderWidth="025"
                    borderColor={isSelected ? "border-focus" : "border"}
                    borderRadius="200"
                    padding="300"
                  >
                    <div
                      role="button"
                      tabIndex={0}
                      style={{ cursor: "pointer" }}
                      onClick={() => onSelectQuestion(index)}
                      onKeyDown={(e) => {
                        if (e.key === "Enter" || e.key === " ") {
                          e.preventDefault();
                          onSelectQuestion(index);
                        }
                      }}
                    >
                      <InlineStack gap="200" blockAlign="center">
                        <Box>
                          <DragHandleIcon
                            aria-label="Drag to reorder"
                            style={{ width: 16, height: 16, color: "var(--p-color-icon-subdued)" }}
                          />
                        </Box>
                        <Box
                          background="bg-fill-info"
                          borderRadius="full"
                          minWidth="24px"
                          minHeight="24px"
                        >
                          <Box padding="050">
                            <Text
                              as="span"
                              variant="bodySm"
                              fontWeight="semibold"
                              tone="text-inverse"
                            >
                              {index + 1}
                            </Text>
                          </Box>
                        </Box>
                        <BlockStack gap="025">
                          <Text
                            as="p"
                            variant="bodySm"
                            fontWeight={isSelected ? "semibold" : "regular"}
                            truncate
                          >
                            {q.title || "Untitled question"}
                          </Text>
                          <Badge tone="info" size="small">
                            {questionTypeLabel(q.type)}
                          </Badge>
                        </BlockStack>
                      </InlineStack>
                    </div>
                  </Box>
                );
              })}
            </BlockStack>
          )}

          <Button icon={PlusIcon} onClick={onAddQuestion} fullWidth variant="primary">
            Add question
          </Button>
        </BlockStack>
      </Layout.Section>

      {/* Right panel — question editor */}
      <Layout.Section>
        {selectedQuestion ? (
          <Card>
            <BlockStack gap="400">
              <InlineStack align="space-between" blockAlign="center">
                <InlineStack gap="200" blockAlign="center">
                  <Text as="h3" variant="headingSm" fontWeight="semibold">
                    Question {selectedQuestionIndex + 1}
                  </Text>
                  <Badge tone="info">{questionTypeLabel(selectedQuestion.type)}</Badge>
                </InlineStack>
                <Button
                  icon={DeleteIcon}
                  tone="critical"
                  variant="plain"
                  onClick={() => onDeleteQuestion(selectedQuestionIndex)}
                  accessibilityLabel="Delete this question"
                >
                  Delete question
                </Button>
              </InlineStack>

              <Divider />

              <FormLayout>
                <TextField
                  label="Question title"
                  value={selectedQuestion.title}
                  onChange={(value) => onUpdateQuestion("title", value)}
                  autoComplete="off"
                  helpText="This is what shoppers will see when taking the quiz."
                />
                <Select
                  label="Question type"
                  options={questionTypeOptions}
                  value={selectedQuestion.type}
                  onChange={(value) => onUpdateQuestion("type", value)}
                  helpText="Choose how shoppers will respond to this question."
                />
                <Checkbox
                  label="Required"
                  helpText="Shoppers must answer this question before proceeding."
                  checked={selectedQuestion.required}
                  onChange={(value) => onUpdateQuestion("required", value)}
                />
              </FormLayout>

              <Divider />

              <BlockStack gap="300">
                <InlineStack align="space-between" blockAlign="center">
                  <Text as="h3" variant="headingSm" fontWeight="semibold">
                    Answer options
                  </Text>
                  <Badge>{String(selectedQuestion.options.length)}</Badge>
                </InlineStack>

                {selectedQuestion.options.length === 0 ? (
                  <Banner tone="warning">
                    <Text as="p" variant="bodySm">
                      This question has no answer options. Add at least one option.
                    </Text>
                  </Banner>
                ) : (
                  <BlockStack gap="200">
                    {selectedQuestion.options.map((option, idx) => (
                      <InlineStack key={option.id} gap="200" blockAlign="center">
                        <Box>
                          <Text as="span" variant="bodySm" tone="subdued">
                            {idx + 1}.
                          </Text>
                        </Box>
                        <Box style={{ flex: 1 }}>
                          <TextField
                            label={`Option ${idx + 1}`}
                            labelHidden
                            value={option.label}
                            onChange={(value) => onUpdateOption(option.id, value)}
                            autoComplete="off"
                            placeholder={`Answer option ${idx + 1}`}
                          />
                        </Box>
                        <Button
                          icon={XIcon}
                          tone="critical"
                          variant="plain"
                          onClick={() => onDeleteOption(option.id)}
                          accessibilityLabel={`Delete option ${idx + 1}`}
                        />
                      </InlineStack>
                    ))}
                  </BlockStack>
                )}

                <Box>
                  <Button icon={PlusIcon} onClick={onAddOption} variant="plain">
                    Add answer option
                  </Button>
                </Box>
              </BlockStack>
            </BlockStack>
          </Card>
        ) : (
          <Card>
            <EmptyState
              heading="Select a question to edit"
              image="https://cdn.shopify.com/s/files/1/0262/4071/2726/files/emptystate-files.png"
              action={{ content: "Add question", onAction: onAddQuestion }}
            >
              <Text as="p" variant="bodyMd" tone="subdued">
                Choose a question from the sidebar, or add a new one to get started.
              </Text>
            </EmptyState>
          </Card>
        )}
      </Layout.Section>
    </Layout>
  );
}

// --- Tab: Product Mapping ---

function ProductMappingTab({
  questions,
  onAddProduct,
  onRemoveProduct,
}: {
  questions: Question[];
  onAddProduct: (questionId: string, optionId: string, product: string) => void;
  onRemoveProduct: (
    questionId: string,
    optionId: string,
    product: string,
  ) => void;
}) {
  const [browseValue, setBrowseValue] = useState<Record<string, string>>({});

  if (questions.length === 0) {
    return (
      <EmptyState
        heading="No questions to map"
        image="https://cdn.shopify.com/s/files/1/0262/4071/2726/files/emptystate-files.png"
      >
        <Text as="p" variant="bodyMd" tone="subdued">
          Add questions with answer options first, then map product tags to each answer.
        </Text>
      </EmptyState>
    );
  }

  return (
    <BlockStack gap="500">
      <Banner tone="info">
        <Text as="p" variant="bodyMd">
          Map Shopify product tags to each answer option. When a shopper selects an answer,
          products with matching tags will be recommended on the results page.
        </Text>
      </Banner>

      {questions.map((question) => (
        <Card key={question.id}>
          <BlockStack gap="400">
            <InlineStack gap="200" blockAlign="center">
              <Box>
                <ProductIcon
                  aria-label="Product mapping"
                  style={{ width: 20, height: 20, color: "var(--p-color-icon-subdued)" }}
                />
              </Box>
              <Text as="h3" variant="headingSm" fontWeight="semibold">
                {question.title || "Untitled question"}
              </Text>
            </InlineStack>

            <Divider />

            {question.options.length === 0 ? (
              <Text as="p" variant="bodySm" tone="subdued">
                This question has no answer options. Add options in the Questions tab.
              </Text>
            ) : (
              <BlockStack gap="400">
                {question.options.map((option) => {
                  const fieldKey = `${question.id}-${option.id}`;
                  return (
                    <Box
                      key={option.id}
                      background="bg-surface-secondary"
                      borderRadius="200"
                      padding="300"
                    >
                      <BlockStack gap="200">
                        <Text as="p" variant="bodyMd" fontWeight="semibold">
                          {option.label || "Untitled option"}
                        </Text>
                        <FormLayout>
                          <InlineStack gap="200" blockAlign="end">
                            <Box style={{ flex: 1 }}>
                              <TextField
                                label="Add product tag"
                                labelHidden
                                value={browseValue[fieldKey] ?? ""}
                                onChange={(value) =>
                                  setBrowseValue((prev) => ({
                                    ...prev,
                                    [fieldKey]: value,
                                  }))
                                }
                                autoComplete="off"
                                placeholder="Enter a product tag (e.g. sensitive-skin)..."
                                helpText="Add Shopify product tags to map products to this answer."
                              />
                            </Box>
                            <Button
                              onClick={() => {
                                const value = browseValue[fieldKey];
                                if (value?.trim()) {
                                  onAddProduct(
                                    question.id,
                                    option.id,
                                    value.trim(),
                                  );
                                  setBrowseValue((prev) => ({
                                    ...prev,
                                    [fieldKey]: "",
                                  }));
                                }
                              }}
                            >
                              Add tag
                            </Button>
                          </InlineStack>
                        </FormLayout>
                        {option.productTags.length > 0 && (
                          <InlineStack gap="100" wrap>
                            {option.productTags.map((tag) => (
                              <Tag
                                key={tag}
                                onRemove={() =>
                                  onRemoveProduct(question.id, option.id, tag)
                                }
                              >
                                {tag}
                              </Tag>
                            ))}
                          </InlineStack>
                        )}
                      </BlockStack>
                    </Box>
                  );
                })}
              </BlockStack>
            )}
          </BlockStack>
        </Card>
      ))}
    </BlockStack>
  );
}

// --- Tab: Design ---

function DesignTab({
  design,
  onUpdateDesign,
}: {
  design: DesignSettings;
  onUpdateDesign: (field: keyof DesignSettings, value: string | boolean) => void;
}) {
  return (
    <Layout>
      {/* Left — settings panel */}
      <Layout.Section>
        <BlockStack gap="400">
          <Card>
            <BlockStack gap="400">
              <Text as="h3" variant="headingSm" fontWeight="semibold">
                Quiz content
              </Text>
              <Divider />
              <FormLayout>
                <TextField
                  label="Quiz title"
                  value={design.quizTitle}
                  onChange={(value) => onUpdateDesign("quizTitle", value)}
                  autoComplete="off"
                  helpText="Displayed as the main heading when shoppers start the quiz."
                />
                <TextField
                  label="Description"
                  value={design.description}
                  onChange={(value) => onUpdateDesign("description", value)}
                  autoComplete="off"
                  multiline={3}
                  helpText="Optional subtitle shown below the quiz title."
                />
              </FormLayout>
            </BlockStack>
          </Card>

          <Card>
            <BlockStack gap="400">
              <Text as="h3" variant="headingSm" fontWeight="semibold">
                Button settings
              </Text>
              <Divider />
              <FormLayout>
                <TextField
                  label="Button color"
                  value={design.buttonColor}
                  onChange={(value) => onUpdateDesign("buttonColor", value)}
                  autoComplete="off"
                  helpText="Enter a hex color code, e.g. #5C6AC4"
                  prefix={
                    <div
                      style={{
                        width: 20,
                        height: 20,
                        borderRadius: 4,
                        backgroundColor: design.buttonColor,
                        border: "1px solid var(--p-color-border)",
                        flexShrink: 0,
                      }}
                    />
                  }
                />
                <TextField
                  label="Button text"
                  value={design.buttonText}
                  onChange={(value) => onUpdateDesign("buttonText", value)}
                  autoComplete="off"
                  helpText='Text shown on the "next" button between questions.'
                />
              </FormLayout>
            </BlockStack>
          </Card>

          <Card>
            <BlockStack gap="400">
              <Text as="h3" variant="headingSm" fontWeight="semibold">
                Results page
              </Text>
              <Divider />
              <FormLayout>
                <TextField
                  label="Results page heading"
                  value={design.resultsHeading}
                  onChange={(value) =>
                    onUpdateDesign("resultsHeading", value)
                  }
                  autoComplete="off"
                  helpText="Shown at the top of the product recommendations page."
                />
                <Checkbox
                  label="Show progress bar"
                  helpText="Displays a progress indicator at the top of the quiz so shoppers know how far along they are."
                  checked={design.showProgressBar}
                  onChange={(value) =>
                    onUpdateDesign("showProgressBar", value)
                  }
                />
              </FormLayout>
            </BlockStack>
          </Card>
        </BlockStack>
      </Layout.Section>

      {/* Right — live preview */}
      <Layout.Section variant="oneThird">
        <Card>
          <BlockStack gap="300">
            <InlineStack align="space-between" blockAlign="center">
              <Text as="h3" variant="headingSm" fontWeight="semibold">
                Preview
              </Text>
              <Badge tone="info">Live</Badge>
            </InlineStack>
            <Divider />

            {/* Phone mockup frame */}
            <Box
              background="bg-surface-secondary"
              borderRadius="300"
              padding="400"
              borderWidth="025"
              borderColor="border"
            >
              <BlockStack gap="300">
                {/* Progress bar */}
                {design.showProgressBar && (
                  <Box
                    background="bg-surface"
                    borderRadius="full"
                    minHeight="6px"
                    borderWidth="025"
                    borderColor="border"
                  >
                    <div
                      style={{
                        width: "33%",
                        height: 6,
                        borderRadius: "var(--p-border-radius-full)",
                        background: design.buttonColor || "#5C6AC4",
                      }}
                    />
                  </Box>
                )}

                {/* Quiz content */}
                <BlockStack gap="200">
                  <Text as="p" variant="headingMd" fontWeight="bold" alignment="center">
                    {design.quizTitle || "Quiz Title"}
                  </Text>
                  {design.description && (
                    <Text as="p" variant="bodySm" tone="subdued" alignment="center">
                      {design.description}
                    </Text>
                  )}
                </BlockStack>

                {/* Sample question */}
                <Box
                  background="bg-surface"
                  borderRadius="200"
                  padding="300"
                  borderWidth="025"
                  borderColor="border"
                >
                  <Text as="p" variant="bodySm" tone="subdued">
                    What is your skin type?
                  </Text>
                </Box>

                {/* Sample answer options */}
                {["Oily", "Dry", "Combination"].map((opt) => (
                  <Box
                    key={opt}
                    background="bg-surface"
                    borderRadius="200"
                    padding="200"
                    borderWidth="025"
                    borderColor="border"
                  >
                    <Text as="p" variant="bodySm">
                      {opt}
                    </Text>
                  </Box>
                ))}

                {/* CTA button */}
                <div
                  style={{
                    display: "flex",
                    justifyContent: "center",
                    marginTop: 4,
                  }}
                >
                  <div
                    style={{
                      display: "inline-block",
                      padding: "8px 24px",
                      borderRadius: 6,
                      backgroundColor: design.buttonColor || "#5C6AC4",
                      color: "#fff",
                      fontSize: 13,
                      fontWeight: 600,
                    }}
                  >
                    {design.buttonText || "Next"}
                  </div>
                </div>
              </BlockStack>
            </Box>

            <Text as="p" variant="bodySm" tone="subdued" alignment="center">
              This preview reflects your current design settings.
            </Text>
          </BlockStack>
        </Card>
      </Layout.Section>
    </Layout>
  );
}

// --- Main Page ---

export default function QuizBuilder() {
  const loaderData = useLoaderData<typeof loader>();
  const actionData = useActionData<typeof action>();
  const navigate = useNavigate();
  const submit = useSubmit();

  const { quiz, questions: initialQuestions, designSettings: initialDesign } =
    loaderData;

  const [questions, setQuestions] = useState<Question[]>(initialQuestions);
  const [selectedQuestionIndex, setSelectedQuestionIndex] = useState(0);
  const [design, setDesign] = useState<DesignSettings>(initialDesign);
  const [selectedTab, setSelectedTab] = useState(0);
  const [deleteModalOpen, setDeleteModalOpen] = useState(false);

  const quizId = quiz.id;

  // Show toast on every action result
  useEffect(() => {
    if (!actionData) return;
    if ("success" in actionData && actionData.success && "message" in actionData) {
      showToast(String(actionData.message), { duration: 3000 });
    } else if ("error" in actionData && actionData.error) {
      showToast(String(actionData.error), {
        duration: 4000,
        isError: true,
      });
    }
  }, [actionData]);

  const tabs = [
    { id: "questions", content: "Questions", panelID: "questions-panel" },
    { id: "mapping", content: "Product Mapping", panelID: "mapping-panel" },
    { id: "design", content: "Design", panelID: "design-panel" },
  ];

  const handleTabChange = useCallback((index: number) => {
    setSelectedTab(index);
  }, []);

  // Save questions tab
  const handleSaveQuestions = useCallback(() => {
    const formData = new FormData();
    formData.set("intent", "save-questions");
    formData.set(
      "questions",
      JSON.stringify(
        questions.map((q, qi) => ({
          id: q.id,
          title: q.title,
          type: q.type,
          required: q.required,
          position: qi,
          options: q.options.map((o, oi) => ({
            id: o.id,
            label: o.label,
            score: o.score,
            productTags: o.productTags,
            position: oi,
          })),
        })),
      ),
    );
    submit(formData, { method: "POST" });
  }, [questions, submit]);

  // Save design tab
  const handleSaveDesign = useCallback(() => {
    const stylingObj = {
      buttonColor: design.buttonColor,
      buttonText: design.buttonText,
      resultsHeading: design.resultsHeading,
      showProgressBar: design.showProgressBar,
    };
    const formData = new FormData();
    formData.set("intent", "save-design");
    formData.set("title", design.quizTitle);
    formData.set("description", design.description);
    formData.set("styling", JSON.stringify(stylingObj));
    submit(formData, { method: "POST" });
  }, [design, submit]);

  const handlePublish = useCallback(() => {
    const formData = new FormData();
    formData.set("intent", "publish");
    submit(formData, { method: "POST" });
  }, [submit]);

  const handleUnpublish = useCallback(() => {
    const formData = new FormData();
    formData.set("intent", "unpublish");
    submit(formData, { method: "POST" });
  }, [submit]);

  const handleDeleteConfirm = useCallback(() => {
    const formData = new FormData();
    formData.set("intent", "delete");
    submit(formData, { method: "POST" });
  }, [submit]);

  const handlePreview = useCallback(() => {
    navigate(`/app/quizzes/${quizId}/preview`);
  }, [navigate, quizId]);

  const handleBack = useCallback(() => {
    navigate("/app/quizzes");
  }, [navigate]);

  // --- Question handlers ---

  const handleSelectQuestion = useCallback((index: number) => {
    setSelectedQuestionIndex(index);
  }, []);

  const handleUpdateQuestion = useCallback(
    (field: string, value: string | boolean) => {
      setQuestions((prev) => {
        const updated = [...prev];
        updated[selectedQuestionIndex] = {
          ...updated[selectedQuestionIndex],
          [field]: value,
        };
        return updated;
      });
    },
    [selectedQuestionIndex],
  );

  const handleAddQuestion = useCallback(() => {
    const newId = `new-${Date.now()}`;
    const newQuestion: Question = {
      id: newId,
      title: "",
      type: "single",
      required: true,
      position: questions.length,
      options: [
        { id: `${newId}a1`, label: "Option 1", score: 0, productTags: [], position: 0 },
        { id: `${newId}a2`, label: "Option 2", score: 0, productTags: [], position: 1 },
      ],
    };
    setQuestions((prev) => [...prev, newQuestion]);
    setSelectedQuestionIndex(questions.length);
  }, [questions.length]);

  const handleDeleteQuestion = useCallback(
    (index: number) => {
      setQuestions((prev) => {
        const updated = prev.filter((_, i) => i !== index);
        return updated;
      });
      setSelectedQuestionIndex((prev) =>
        prev >= index && prev > 0 ? prev - 1 : prev,
      );
    },
    [],
  );

  const handleAddOption = useCallback(() => {
    setQuestions((prev) => {
      const updated = [...prev];
      const question = { ...updated[selectedQuestionIndex] };
      const newOptionId = `${question.id}a${Date.now()}`;
      question.options = [
        ...question.options,
        {
          id: newOptionId,
          label: "",
          score: 0,
          productTags: [],
          position: question.options.length,
        },
      ];
      updated[selectedQuestionIndex] = question;
      return updated;
    });
  }, [selectedQuestionIndex]);

  const handleUpdateOption = useCallback(
    (optionId: string, value: string) => {
      setQuestions((prev) => {
        const updated = [...prev];
        const question = { ...updated[selectedQuestionIndex] };
        question.options = question.options.map((opt) =>
          opt.id === optionId ? { ...opt, label: value } : opt,
        );
        updated[selectedQuestionIndex] = question;
        return updated;
      });
    },
    [selectedQuestionIndex],
  );

  const handleDeleteOption = useCallback(
    (optionId: string) => {
      setQuestions((prev) => {
        const updated = [...prev];
        const question = { ...updated[selectedQuestionIndex] };
        question.options = question.options.filter(
          (opt) => opt.id !== optionId,
        );
        updated[selectedQuestionIndex] = question;
        return updated;
      });
    },
    [selectedQuestionIndex],
  );

  // --- Product mapping handlers ---

  const handleAddProduct = useCallback(
    (questionId: string, optionId: string, tag: string) => {
      setQuestions((prev) =>
        prev.map((q) =>
          q.id === questionId
            ? {
                ...q,
                options: q.options.map((opt) =>
                  opt.id === optionId
                    ? {
                        ...opt,
                        productTags: [...opt.productTags, tag],
                      }
                    : opt,
                ),
              }
            : q,
        ),
      );
    },
    [],
  );

  const handleRemoveProduct = useCallback(
    (questionId: string, optionId: string, tag: string) => {
      setQuestions((prev) =>
        prev.map((q) =>
          q.id === questionId
            ? {
                ...q,
                options: q.options.map((opt) =>
                  opt.id === optionId
                    ? {
                        ...opt,
                        productTags: opt.productTags.filter((t) => t !== tag),
                      }
                    : opt,
                ),
              }
            : q,
        ),
      );
    },
    [],
  );

  // --- Design handlers ---

  const handleUpdateDesign = useCallback(
    (field: keyof DesignSettings, value: string | boolean) => {
      setDesign((prev) => ({ ...prev, [field]: value }));
    },
    [],
  );

  // Current save action depends on active tab
  const handleSave = useCallback(() => {
    if (selectedTab === 2) {
      handleSaveDesign();
    } else {
      handleSaveQuestions();
    }
  }, [selectedTab, handleSaveDesign, handleSaveQuestions]);

  const isLive = quiz.status === "active";
  const statusTone = isLive
    ? "success"
    : quiz.status === "draft"
      ? "attention"
      : undefined;
  const statusLabel = isLive ? "Live" : "Draft";

  return (
    <>
      <Page
        title={quiz.title}
        backAction={{ content: "Quizzes", onAction: handleBack }}
        titleMetadata={<Badge tone={statusTone}>{statusLabel}</Badge>}
        primaryAction={{
          content: "Save",
          icon: SaveIcon,
          onAction: handleSave,
        }}
        secondaryActions={[
          {
            content: "Preview",
            icon: EyeFirstIcon,
            onAction: handlePreview,
          },
          isLive
            ? {
                content: "Unpublish",
                onAction: handleUnpublish,
              }
            : {
                content: "Publish",
                onAction: handlePublish,
              },
          {
            content: "Delete quiz",
            destructive: true,
            icon: DeleteIcon,
            onAction: () => setDeleteModalOpen(true),
          },
        ]}
      >
        <BlockStack gap="400">
          <Card padding="0">
            <Tabs tabs={tabs} selected={selectedTab} onSelect={handleTabChange} fitted>
              <Box padding="400">
                {selectedTab === 0 && (
                  <QuestionsTab
                    questions={questions}
                    selectedQuestionIndex={selectedQuestionIndex}
                    onSelectQuestion={handleSelectQuestion}
                    onUpdateQuestion={handleUpdateQuestion}
                    onAddQuestion={handleAddQuestion}
                    onAddOption={handleAddOption}
                    onUpdateOption={handleUpdateOption}
                    onDeleteOption={handleDeleteOption}
                    onDeleteQuestion={handleDeleteQuestion}
                  />
                )}
                {selectedTab === 1 && (
                  <ProductMappingTab
                    questions={questions}
                    onAddProduct={handleAddProduct}
                    onRemoveProduct={handleRemoveProduct}
                  />
                )}
                {selectedTab === 2 && (
                  <DesignTab
                    design={design}
                    onUpdateDesign={handleUpdateDesign}
                  />
                )}
              </Box>
            </Tabs>
          </Card>
        </BlockStack>
      </Page>

      {/* Delete confirmation modal */}
      <Modal
        open={deleteModalOpen}
        onClose={() => setDeleteModalOpen(false)}
        title="Delete quiz?"
        primaryAction={{
          content: "Delete",
          destructive: true,
          onAction: handleDeleteConfirm,
        }}
        secondaryActions={[
          {
            content: "Cancel",
            onAction: () => setDeleteModalOpen(false),
          },
        ]}
      >
        <Modal.Section>
          <BlockStack gap="200">
            <Text as="p" variant="bodyMd">
              Are you sure you want to delete <strong>{quiz.title}</strong>?
            </Text>
            <Text as="p" variant="bodyMd" tone="subdued">
              This will permanently delete the quiz, all its questions, answers, and
              response data. This action cannot be undone.
            </Text>
          </BlockStack>
        </Modal.Section>
      </Modal>
    </>
  );
}

export const headers: HeadersFunction = (headersArgs) => {
  return boundary.headers(headersArgs);
};
